import { expect, test, type Page } from '@playwright/test'

type RuntimeDebug = { paused: boolean; pauseReason: string; journal: string[] }

/**
 * PÄ™tla 120 Hz celowo przechodzi w pauzÄ™, gdy klatka przekroczy limit
 * nadrabiania. Pod obciÄ…ĹĽeniem automatyzacji zdarza siÄ™ to takĹĽe tuĹĽ po
 * wznowieniu, dlatego wznawiamy do skutku i sprawdzamy, ĹĽe powodem jest
 * wyĹ‚Ä…cznie ten udokumentowany mechanizm, a nie inny bĹ‚Ä…d stanu.
 */
async function resumeIfPaused(page: Page, attempts = 8): Promise<void> {
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    const state = await page.evaluate(() => (
      window as unknown as { __retroDebugSnapshot: () => RuntimeDebug }
    ).__retroDebugSnapshot())
    if (!state.paused) return
    if (attempt > 0) {
      expect(state.pauseReason).toBe('zbyt dĹ‚uga przerwa klatki')
    }
    await page.keyboard.press('Enter')
  }
}

test('shell dziaĹ‚a klawiaturÄ…, skaluje obraz i przeĹĽywa odmowÄ™ API', async ({ page }) => {
  await page.addInitScript(() => {
    const state = { fullscreenCalls: 0, audioCalls: 0 }
    Object.defineProperty(window, '__apiTestState', { value: state })
    Element.prototype.requestFullscreen = () => {
      state.fullscreenCalls += 1
      return Promise.reject(new Error('celowa odmowa testowa'))
    }

    class RejectedAudioContext {
      state = 'suspended'
      resume() {
        state.audioCalls += 1
        return Promise.reject(new Error('celowa blokada audio'))
      }
    }
    Object.defineProperty(window, 'AudioContext', { value: RejectedAudioContext })
  })

  await page.setViewportSize({ width: 1280, height: 720 })
  await page.goto('/', { waitUntil: 'domcontentloaded' })

  const canvas = page.locator('#game-canvas')
  await expect(canvas).toHaveAttribute('width', '960')
  await expect(canvas).toHaveAttribute('height', '540')
  await expect(canvas).toHaveAttribute('aria-label', /ekran tytuĹ‚owy/)
  await expect.poll(() => page.evaluate(() => ({
    scrollWidth: document.documentElement.scrollWidth,
    width: innerWidth,
    canvas: document.querySelector('canvas')?.getBoundingClientRect().toJSON(),
  }))).toMatchObject({
    scrollWidth: 1280,
    width: 1280,
    canvas: { width: 1280, height: 720 },
  })
  await page.screenshot({ path: 'docs/evidence/PKG-008/browser-artifacts/regression-title-1280x720.png' })

