  label(context, `BELKA REF ${result.gate.referenceGateNumber} / JURY ${result.gate.juryGateNumber} / COACH ${result.gate.coachRequested ? 'TAK' : 'NIE'}`, 411, 187, COLOR.snowShade, 6)
