import type { FeedbackCode, TrainingJumpResult } from '../sport/jumpResult'
import { buildSportMarkers, type PositionedMarker, type SportMarkerSet } from './sportMarkers'
import { drawPixelText, type PixelTextAlign } from './pixelFont'

export const VIEW_WIDTH = 480
export const VIEW_HEIGHT = 270

/** Oznaczenia sportowe â€” kontrakt kolorĂłw z ART_UI_AUDIO Â§5, niezaleĹĽny od rodziny palety. */
const SPORT = {
  steel: '#536c7a',
  warm: '#f1bd79',
  text: '#f3ead1',
