/**
 * Minimalny kontrakt sceny produkcyjnej. `JumpSimulation` speĹ‚nia go strukturalnie
 * (ma dodatkowe pola), a `ReplayPlayer` buduje z tego samego ksztaĹ‚tu adapter na
 * podstawie `ReplayFrame` â€” bez zmiany formatu zapisanego replaya (decyzja #5).
 */
export type SceneActor = {
  readonly hill: Hill
  readonly phase: string
  readonly position: Vec2
  readonly pitchRad: number
  readonly tick: number
}

/** StaĹ‚y zoom; kamera utrzymuje zawodnika przy 38% szerokoĹ›ci bez skokĂłw zoomu. */
export function buildProductionCamera(actor: SceneActor): WorldView {
  const scale = 2.075
  const anchorX = VIEW_WIDTH * 0.38
  const anchorY = actor.phase === 'GateGreen' || actor.phase === 'Inrun' || actor.phase === 'Takeoff' ? 103 : 111
  const focus = actor.position
  return {
    scale,
    toScreen: (point) => ({
      x: anchorX + (point.x - focus.x) * scale,
      y: anchorY - (point.y - focus.y) * scale,
    }),
  }
}

function drawFloodlight(context: CanvasRenderingContext2D, x: number, baseY: number, height: number): void {
  pixelLine(context, x, baseY, x + 4, baseY - height, env().steelDark, 2)
  pixelLine(context, x + 4, baseY - height, x + 17, baseY - height - 2, COLOR.steel, 2)
  context.fillStyle = COLOR.warm
  for (let lamp = 0; lamp < 4; lamp += 1) {
    context.fillRect(x + 5 + lamp * 4, baseY - height - 4, 3, 3)
  }
  fillPixelPolygon(context, env().floodlightGlow, [
    [x + 4, baseY - height], [x + 20, baseY - height], [x + 42, baseY], [x - 10, baseY],
  ])
}

function drawStadium(context: CanvasRenderingContext2D, shiftX: number): void {
  // RÄ™cznie zaprojektowana reprezentatywna trybuna: dach, kratownica,
  // cztery poziomy siedzeĹ„, wieĹĽa wynikĂłw i pikselowy tĹ‚um.
  const palette = env()
  const s = shiftX
  fillPixelPolygon(context, palette.steelDark, [[228 + s, 142], [467 + s, 142], [454 + s, 187], [239 + s, 187]])
  fillPixelPolygon(context, COLOR.steel, [[219 + s, 136], [475 + s, 136], [463 + s, 143], [229 + s, 143]])
  fillPixelPolygon(context, palette.steelMid, [[228 + s, 143], [467 + s, 143], [459 + s, 150], [232 + s, 150]])
  for (let x = 237; x <= 459; x += 28) {
    pixelLine(context, x + s, 144, x - 7 + s, 187, '#405a69', 1)
    pixelLine(context, x - 7 + s, 187, x + 21 + s, 144, palette.steelMid, 1)
  }
  for (let row = 0; row < 4; row += 1) {
    const y = 154 + row * 8
