): void {
  if (state.technicalView) {
    drawTechnicalJumpScreen(context, sim, technicalView, state)
    label(context, 'D â€” POWRĂ“T DO SCENY PRODUKCYJNEJ', 10, 41, COLOR.warm, 7)
    return
  }

  context.imageSmoothingEnabled = false
  drawProductionScene(context, sim, buildProductionCamera(sim), state, sim.currentWindUserMetersPerSecond)
  drawLiveHud(context, sim, state)
  if (state.result) drawResultScreen(context, sim, state)
}

/**
 * TĹ‚o + teren + skoczek + cieĹ„, bez HUD-u ekranu gry. WspĂłĹ‚dzielony przez
 * scenÄ™ treningu/konkursu i produkcyjnÄ… scenÄ™ powtĂłrki (decyzja #5).
 */
export function drawProductionScene(
  context: CanvasRenderingContext2D,
  actor: SceneActor,
  view: WorldView,
  state: TrainingSceneState,
  windUserMetersPerSecond: number,
): void {
  context.imageSmoothingEnabled = false
  drawProductionBackground(context, actor.tick, state.snowEnabled, windUserMetersPerSecond, actor.position.x, view.scale)
  drawProductionTerrain(context, actor, view, state)
  drawProductionJumper(context, view, actor)
}

