  drawJumper(context, view, sim)

  drawPanel(context, 9, VIEW_HEIGHT - 48, 210, 39)
  label(context, PHASE_LABEL[sim.phase] ?? sim.phase, 15, VIEW_HEIGHT - 36, COLOR.warm, 9)
  const distanceText = sim.measuredDistanceMeters === null ? 'â€”' : `${sim.measuredDistanceMeters.toFixed(1)} M`
  label(context, `ODLEGĹ�OĹšÄ†: ${distanceText}`, 15, VIEW_HEIGHT - 25, COLOR.text, 9)
  const styleText = sim.landingStyle === 'none' ? 'BRAK (T / R)' : sim.landingStyle === 'telemark' ? 'TELEMARK' : 'DWIE NOGI'
  label(context, `PRZYGOTOWANIE: ${styleText}`, 15, VIEW_HEIGHT - 15, COLOR.snowShade, 9)

  const journal = sim.events.slice(-5)
  drawPanel(context, 226, VIEW_HEIGHT - 48, VIEW_WIDTH - 235, 39)
  journal.forEach((event, index) => {
