  Inrun: 'ROZBIEG',
  Takeoff: 'PRĂ“G â€” â†‘ WYBICIE',
  Flight: 'LOT â€” â†� â†’ POZYCJA',
  LandingPrep: 'PRZYGOTOWANIE LÄ„DOWANIA',
