/**
 * Minimalny kontrakt sceny produkcyjnej. `JumpSimulation` speĹ‚nia go strukturalnie
 * (ma dodatkowe pola), a `ReplayPlayer` buduje z tego samego ksztaĹ‚tu adapter na
 * podstawie `ReplayFrame` â€” bez zmiany formatu zapisanego replaya (decyzja #5).
 */
export type SceneActor = {
  readonly hill: Hill
  readonly phase: string
  readonly position: Vec2
  readonly pitchRad: number
  readonly tick: number
}

/** StaĹ‚y zoom; kamera utrzymuje zawodnika przy 38% szerokoĹ›ci bez skokĂłw zoomu. */
export function buildProductionCamera(actor: SceneActor): WorldView {
  const scale = 2.075
  const anchorX = VIEW_WIDTH * 0.38
  const anchorY = actor.phase === 'GateGreen' || actor.phase === 'Inrun' || actor.phase === 'Takeoff' ? 103 : 111
  const focus = actor.position
  return {
    scale,
    toScreen: (point) => ({
      x: anchorX + (point.x - focus.x) * scale,
      y: anchorY - (point.y - focus.y) * scale,
    }),
  }
}

function drawFloodlight(context: CanvasRenderingContext2D, x: number, baseY: number, height: number): void {
  pixelLine(context, x, baseY, x + 4, baseY - height, env().steelDark, 2)
  pixelLine(context, x + 4, baseY - height, x + 17, baseY - height - 2, COLOR.steel, 2)
  context.fillStyle = COLOR.warm
  for (let lamp = 0; lamp < 4; lamp += 1) {
    context.fillRect(x + 5 + lamp * 4, baseY - height - 4, 3, 3)
  }
  fillPixelPolygon(context, env().floodlightGlow, [
    [x + 4, baseY - height], [x + 20, baseY - height], [x + 42, baseY], [x - 10, baseY],
  ])
}

function drawStadium(context: CanvasRenderingContext2D, shiftX: number): void {
  // RÄ™cznie zaprojektowana reprezentatywna trybuna: dach, kratownica,
  // cztery poziomy siedzeĹ„, wieĹĽa wynikĂłw i pikselowy tĹ‚um.
  const palette = env()
  const s = shiftX
  fillPixelPolygon(context, palette.steelDark, [[228 + s, 142], [467 + s, 142], [454 + s, 187], [239 + s, 187]])
  fillPixelPolygon(context, COLOR.steel, [[219 + s, 136], [475 + s, 136], [463 + s, 143], [229 + s, 143]])
  fillPixelPolygon(context, palette.steelMid, [[228 + s, 143], [467 + s, 143], [459 + s, 150], [232 + s, 150]])
  for (let x = 237; x <= 459; x += 28) {
    pixelLine(context, x + s, 144, x - 7 + s, 187, '#405a69', 1)
    pixelLine(context, x - 7 + s, 187, x + 21 + s, 144, palette.steelMid, 1)
  }
  for (let row = 0; row < 4; row += 1) {
    const y = 154 + row * 8
    context.fillStyle = row % 2 === 0 ? '#172b3b' : '#20394a'
    context.fillRect(237 + s, y - 4, 219, 6)
    for (let x = 240; x < 454; x += 5) {
      context.fillStyle = palette.crowd[Math.floor(x / 5 + row * 3) % palette.crowd.length] ?? COLOR.text
      context.fillRect(x + s, y - ((x + row) % 2), 2, 2)
    }
  }
  context.fillStyle = '#08111c'
  context.fillRect(388 + s, 119, 58, 21)
  context.strokeStyle = COLOR.steel
  context.lineWidth = 1
  context.strokeRect(388.5 + s, 119.5, 57, 20)
  context.fillStyle = COLOR.green
  context.fillRect(394 + s, 125, 4, 9)
  context.fillStyle = COLOR.red
  context.fillRect(400 + s, 127, 4, 7)
  context.fillStyle = COLOR.warm
  context.fillRect(408 + s, 123, 31, 2)
  context.fillRect(408 + s, 128, 23, 2)
  context.fillRect(408 + s, 133, 27, 2)
}

/**
 * Warstwy paralaksy kosztujÄ… duĹĽo (wielokÄ…ty gĂłr/lasu/trybun rasteryzowane
 * skanliniowo, bez antyaliasingu â€” patrz `fillPixelPolygon`). Rysowanie ich
 * na nowo w kaĹĽdej klatce mierzalnie obciÄ…ĹĽaĹ‚o budĹĽet 120 Hz (P15). Zamiast
 * tego renderujemy kaĹĽdÄ… warstwÄ™ RAZ do bufora szerszego niĹĽ ekran, a co
 * klatkÄ™ tylko przesuwamy jÄ… caĹ‚kowitÄ… liczbÄ… pikseli przez `drawImage`
 * (tania operacja) â€” piksele w obrÄ™bie warstwy siÄ™ nie zmieniajÄ…, tylko jej
 * pozycja pozioma zaleĹĽna od paralaksy (decyzja #4, P42 Â§5 opcja D).
 */
const BG_MARGIN = 50
const BG_LAYER_OFFSET = 40 + BG_MARGIN
const BG_LAYER_WIDTH = 560 + BG_MARGIN * 2
let backgroundLayers: { far: OffscreenCanvas | HTMLCanvasElement; mid: OffscreenCanvas | HTMLCanvasElement; near: OffscreenCanvas | HTMLCanvasElement } | null = null
let backgroundLayersFamily: PaletteFamilyId | null = null

function makeLayerCanvas(): OffscreenCanvas | HTMLCanvasElement {
  return typeof OffscreenCanvas === 'function'
    ? new OffscreenCanvas(BG_LAYER_WIDTH, VIEW_HEIGHT)
    : Object.assign(document.createElement('canvas'), { width: BG_LAYER_WIDTH, height: VIEW_HEIGHT })
}

function buildBackgroundLayers(): void {
  const palette = env()
  const o = BG_LAYER_OFFSET

  const far = makeLayerCanvas()
  const farContext = far.getContext('2d') as CanvasRenderingContext2D
  farContext.imageSmoothingEnabled = false
  fillPixelPolygon(farContext, palette.mountainFar, [[-40 + o, 152], [7 + o, 88], [45 + o, 123], [113 + o, 63], [165 + o, 126], [234 + o, 77], [297 + o, 130], [362 + o, 59], [520 + o, 136], [520 + o, 210], [-40 + o, 210]])

  const mid = makeLayerCanvas()
  const midContext = mid.getContext('2d') as CanvasRenderingContext2D
  midContext.imageSmoothingEnabled = false
  fillPixelPolygon(midContext, palette.mountainNear, [[8 + o, 114], [27 + o, 88], [40 + o, 104], [133 + o, 63], [155 + o, 91], [254 + o, 77], [267 + o, 94], [382 + o, 59], [402 + o, 85], [427 + o, 102], [520 + o, 136], [520 + o, 146], [-40 + o, 146]])
  fillPixelPolygon(midContext, palette.mountainMid, [[-40 + o, 166], [46 + o, 121], [97 + o, 155], [166 + o, 106], [231 + o, 159], [300 + o, 115], [363 + o, 163], [429 + o, 109], [520 + o, 146], [520 + o, 210], [-40 + o, 210]])
  drawStadium(midContext, o)
  drawFloodlight(midContext, 207 + o, 195, 71)
  drawFloodlight(midContext, 452 + o, 194, 63)

  const near = makeLayerCanvas()
  const nearContext = near.getContext('2d') as CanvasRenderingContext2D
  nearContext.imageSmoothingEnabled = false
  for (const [x, height] of [[-24, 26], [0, 18], [16, 24], [35, 16], [53, 29], [65, 20], [88, 25], [112, 17], [147, 27], [175, 21], [202, 25]] as const) {
    const bx = x + o
    fillPixelPolygon(nearContext, palette.forestCanopy, [[bx, 201], [bx + 7, 201 - height], [bx + 13, 201], [bx + 13, 215], [bx, 215]])
    nearContext.fillStyle = palette.forestShade
    nearContext.fillRect(Math.round(bx + 5), 201 - Math.floor(height * 0.55), 3, Math.floor(height * 0.55) + 14)
  }

  backgroundLayers = { far, mid, near }
  backgroundLayersFamily = activePaletteFamily
}

function drawProductionBackground(
  context: CanvasRenderingContext2D,
  tick: number,
  snowEnabled: boolean,
  windUserMetersPerSecond: number,
  focusMeters: number,
  scale: number,
): void {
  const palette = env()
  context.fillStyle = palette.skyBands[0]
  context.fillRect(0, 0, VIEW_WIDTH, VIEW_HEIGHT)
  palette.skyBands.forEach((color, index) => {
    context.fillStyle = color
    context.fillRect(0, index * 37, VIEW_WIDTH, 38)
  })

  if (!backgroundLayers || backgroundLayersFamily !== activePaletteFamily) buildBackgroundLayers()
  const layers = backgroundLayers
  if (layers) {
    // Paralaksa: warstwy dalsze przesuwajÄ… siÄ™ wolniej niĹĽ kamera (decyzja #4).
    const farShift = -focusMeters * scale * 0.06
    const midShift = -focusMeters * scale * 0.1
    const nearShift = -focusMeters * scale * 0.15
    context.drawImage(layers.far, Math.round(farShift) - BG_LAYER_OFFSET, 0)
    context.drawImage(layers.mid, Math.round(midShift) - BG_LAYER_OFFSET, 0)
    context.drawImage(layers.near, Math.round(nearShift) - BG_LAYER_OFFSET, 0)
  }

  if (!snowEnabled) return
  for (let index = 0; index < 64; index += 1) {
    const drift = -windUserMetersPerSecond * (1.2 + (index % 4) * 0.3)
    const x = ((index * 41 + tick * (0.23 + (index % 3) * 0.09) + drift * tick * 0.04) % VIEW_WIDTH + VIEW_WIDTH) % VIEW_WIDTH
    const y = (index * 24 + tick * (0.38 + (index % 2) * 0.18)) % 210
    const large = index % 7 === 0
    context.fillStyle = large ? 'rgba(243, 234, 209, 0.90)' : 'rgba(231, 240, 239, 0.68)'
    context.fillRect(Math.round(x), Math.round(y), 1, large ? 2 : 1)
  }
}

function traceCurvePoints(
  view: WorldView,
  curve: ProfileCurve,
  strideMeters = 0.75,
): Vec2[] {
  const stride = Math.max(1, Math.round(strideMeters / curve.step))
  const points: Vec2[] = []
  for (let index = 0; index < curve.points.length; index += stride) {
    const point = curve.points[index]
    if (!point) continue
    points.push(view.toScreen(point))
  }
  points.push(view.toScreen(curve.lastPoint))
  return points
}

function drawInrunStructure(context: CanvasRenderingContext2D, hill: Hill, view: WorldView): void {
  const palette = env()
  const supportDistances = [8, 25, 43, 61, 78, 91]
  for (const distanceMeters of supportDistances) {
    const top = view.toScreen(hill.inrunCurve.positionAt(distanceMeters))
    const footingY = Math.min(VIEW_HEIGHT + 20, top.y + 29 + distanceMeters * 0.21)
    pixelLine(context, top.x, top.y + 2, top.x - 4, footingY, '#3c5565', 2)
    pixelLine(context, top.x + 4, top.y + 2, top.x + 9, footingY, palette.steelMid, 2)
    pixelLine(context, top.x - 4, footingY, top.x + 9, footingY, COLOR.steel, 1)
    pixelLine(context, top.x - 3, top.y + 9, top.x + 7, top.y + 21, palette.steelMid, 1)
    pixelLine(context, top.x + 7, top.y + 9, top.x - 2, top.y + 21, '#405a69', 1)
  }

  const tower = view.toScreen(hill.inrunCurve.positionAt(4))
  context.fillStyle = palette.steelDark
  context.fillRect(Math.round(tower.x - 13), Math.round(tower.y - 14), 25, 15)
  context.strokeStyle = COLOR.steel
  context.lineWidth = 1
  context.strokeRect(Math.round(tower.x - 12) + 0.5, Math.round(tower.y - 13) + 0.5, 24, 13)
  context.fillStyle = COLOR.warm
  context.fillRect(Math.round(tower.x - 9), Math.round(tower.y - 10), 5, 4)
  context.fillStyle = COLOR.green
  context.fillRect(Math.round(tower.x + 5), Math.round(tower.y - 10), 4, 4)
}

/**
 * Sama sylwetka toru (krzywe, oznaczenia, konstrukcja rozbiegu) zaleĹĽy tylko
 * od skoczni i stanu markerĂłw, nie od pozycji zawodnika â€” kamera ma staĹ‚Ä…
 * skalÄ™ (patrz `buildProductionCamera`), wiÄ™c jej przesuniÄ™cie to czysta
 * translacja. Rysujemy jÄ… raz do bufora i co klatkÄ™ tylko przesuwamy przez
 * `drawImage` (ten sam wzorzec co `profileLayer` dla widoku technicznego),
 * zamiast setek `fillRect` z `pixelLine`/`fillPixelPolygon` na klatkÄ™ â€” to
 * byĹ‚ mierzalny koszt budĹĽetu 120 Hz po przejĹ›ciu na rysowanie pikselowe.
 */
function drawProductionTerrainStatic(
  context: CanvasRenderingContext2D,
  hill: Hill,
  view: WorldView,
): void {
  const landingStart = view.toScreen(hill.landingCurve.firstPoint)
  const outrunEnd = view.toScreen(hill.outrunCurve.lastPoint)

  const terrainPoints: Array<[number, number]> = [[-40, landingStart.y], [landingStart.x, landingStart.y]]
  for (const point of traceCurvePoints(view, hill.landingCurve)) terrainPoints.push([point.x, point.y])
  for (const point of traceCurvePoints(view, hill.outrunCurve)) terrainPoints.push([point.x, point.y])
  terrainPoints.push([VIEW_WIDTH + 40, outrunEnd.y], [VIEW_WIDTH + 40, VIEW_HEIGHT + 20], [-40, VIEW_HEIGHT + 20])
  fillPixelPolygon(context, '#152838', terrainPoints)

  drawInrunStructure(context, hill, view)
  strokeCurve(context, view, hill.landingCurve, COLOR.snowShade, 9, 0.75)
  strokeCurve(context, view, hill.outrunCurve, COLOR.snowShade, 9, 0.75)
  strokeCurve(context, view, hill.landingCurve, COLOR.snow, 6, 0.75)
  strokeCurve(context, view, hill.outrunCurve, COLOR.snow, 6, 0.75)
  strokeCurve(context, view, hill.inrunCurve, env().steelMid, 6, 0.75)
  strokeCurve(context, view, hill.inrunCurve, COLOR.snow, 3, 0.75)

  const table = view.toScreen(hill.markers.tableEdge)
  const landing = view.toScreen(hill.landingCurve.firstPoint)
  pixelLine(context, table.x, table.y, landing.x, landing.y, COLOR.steel, 3)
  context.fillStyle = COLOR.warm
  context.fillRect(Math.round(table.x - 2), Math.round(table.y - 4), 4, 7)

  // Bez `leadingTargetHalfMeters`/`recordHalfMeters`: te dwa markery zaleĹĽÄ… od
  // ĹĽywego stanu (wiatr zmienia siÄ™ co tick) i rysujÄ… siÄ™ osobno, na ĹĽywo,
  // w `drawProductionTerrain` â€” inaczej klucz bufora zmieniaĹ‚by siÄ™ co klatkÄ™.
  const sportMarkers = buildSportMarkers(hill)
  for (const band of sportMarkers.sideBands) {
    drawBothSideBands(context, view, hill, band.fromMeters, band.toMeters, colorForBand(band.kind))
  }

  context.textAlign = 'center'
  for (const marker of sportMarkers.meterLines) {
    drawSurfaceTick(context, view, hill, marker.meters, 1.05, COLOR.steel, 1)
    // Co 20 m zamiast co 10 m: na stromym progu K/HS kolejne dziesiÄ…tki
    // metrĂłw leĹĽÄ… na ekranie zbyt blisko siebie i etykiety by siÄ™ nakĹ‚adaĹ‚y.
    if (marker.meters % 20 === 0) {
      const normal = hill.surfaceNormalAt(marker.meters)
      const point = view.toScreen({ x: marker.point.x + normal.x * 3.4, y: marker.point.y + normal.y * 3.4 })
      label(context, `${marker.meters}`, point.x, point.y + 3, COLOR.text, 6)
    }
  }
  drawSidePaddles(context, view, hill, sportMarkers, false)
  drawNamedSportMarker(context, view, hill, sportMarkers.kPoint, 'K', COLOR.blue, false)
  drawNamedSportMarker(context, view, hill, sportMarkers.hillSize, 'HS', COLOR.red, false)
  drawNamedSportMarker(context, view, hill, sportMarkers.fallLine, 'FALL', COLOR.warm, false)
  context.textAlign = 'left'
}

type TerrainBuffer = {
  readonly canvas: OffscreenCanvas | HTMLCanvasElement
  readonly minX: number
  readonly maxY: number
}

let terrainBuffer: TerrainBuffer | null = null
let terrainBufferKey = ''

function buildTerrainBuffer(hill: Hill): TerrainBuffer {
  const scale = 2.075 // musi byÄ‡ identyczne z `buildProductionCamera`
  const margin = 24
  const xs: number[] = []
  const ys: number[] = []
  for (const curve of [hill.inrunCurve, hill.landingCurve, hill.outrunCurve]) {
    xs.push(curve.firstPoint.x, curve.lastPoint.x)
    ys.push(curve.firstPoint.y, curve.lastPoint.y)
  }
  const minX = Math.min(...xs) - margin / scale
  const maxX = Math.max(...xs) + margin / scale
  const minY = Math.min(...ys) - margin / scale
  // Konstrukcja wieĹĽy startowej i stadion siÄ™gajÄ… wyĹĽej niĹĽ sama krzywa rozbiegu.
  const maxY = Math.max(...ys) + (margin + 40) / scale

  const width = Math.ceil((maxX - minX) * scale)
  const height = Math.ceil((maxY - minY) * scale)
  const canvas = typeof OffscreenCanvas === 'function'
    ? new OffscreenCanvas(width, height)
    : Object.assign(document.createElement('canvas'), { width, height })
  const context = canvas.getContext('2d') as CanvasRenderingContext2D
  context.imageSmoothingEnabled = false
  const referenceView: WorldView = {
    scale,
    toScreen: (point) => ({ x: (point.x - minX) * scale, y: (maxY - point.y) * scale }),
  }
  drawProductionTerrainStatic(context, hill, referenceView)
  return { canvas, minX, maxY }
}

function drawProductionTerrain(
  context: CanvasRenderingContext2D,
  actor: SceneActor,
  view: WorldView,
  state: TrainingSceneState,
): void {
  const hill = actor.hill
  const key = `${hill.spec.id}:${hill.spec.hillVersion}`
  if (!terrainBuffer || terrainBufferKey !== key) {
    terrainBuffer = buildTerrainBuffer(hill)
    terrainBufferKey = key
  }
  const origin = view.toScreen({ x: terrainBuffer.minX, y: terrainBuffer.maxY })
  context.drawImage(terrainBuffer.canvas, Math.round(origin.x), Math.round(origin.y))

  // ZaleĹĽÄ… od ĹĽywego stanu (wiatr, cel do prowadzenia) â€” rysowane co klatkÄ™.
  const dynamicMarkers = buildSportMarkers(hill, {
    leadingTargetHalfMeters: state.leadingTargetHalfMeters,
    recordHalfMeters: state.recordHalfMeters,
  })
  context.textAlign = 'center'
  drawDynamicMarkers(context, view, hill, dynamicMarkers)
  context.textAlign = 'left'

  drawJumperShadow(context, view, actor)
}

/** PĹ‚aski, ciemny cieĹ„ rzutowany na Ĺ›nieg pod skoczkiem (opcja E, REPORT.md Â§5). */
function drawJumperShadow(context: CanvasRenderingContext2D, view: WorldView, actor: SceneActor): void {
  const groundY = actor.hill.surfaceYAtX(actor.position.x)
  const heightAboveSurface = Math.max(0, actor.position.y - groundY)
  if (heightAboveSurface > 40) return
  const ground = view.toScreen({ x: actor.position.x, y: groundY })
  const fade = Math.max(0.18, 1 - heightAboveSurface / 40)
  const halfWidth = Math.max(2, 7 * fade)
  const halfHeight = Math.max(1, 2 * fade)
  fillPixelPolygon(context, `rgba(7, 17, 31, ${(0.45 * fade).toFixed(2)})`, ellipsePoints(ground.x, ground.y, halfWidth, halfHeight))
}

/**
 * TryskajÄ…cy Ĺ›nieg przy kontakcie nart z podĹ‚oĹĽem â€” jedyny nowy efekt
 * odczucia skoku (rozbieĹĽnoĹ›Ä‡ #8, REPORT.md PKG-007 Â§4). Czysta funkcja
 * fazy/wysokoĹ›ci/ticku, bez stanu miÄ™dzy klatkami i bez zmiany fizyki.
 */
function drawContactSpray(context: CanvasRenderingContext2D, view: WorldView, actor: SceneActor): void {
  if (actor.phase !== 'LandingPrep' && actor.phase !== 'Outrun' && actor.phase !== 'FinishLine') return
  const groundY = actor.hill.surfaceYAtX(actor.position.x)
  const heightAboveSurface = actor.position.y - groundY
  if (heightAboveSurface > 1.1 || heightAboveSurface < -0.6) return
  const ground = view.toScreen({ x: actor.position.x, y: groundY })
  for (let index = 0; index < 7; index += 1) {
    const seed = actor.tick * 11 + index * 17
    const dx = -3 - (seed % 10)
    const dy = -1 - ((seed * 3) % 5)
    context.fillStyle = index % 3 === 0 ? 'rgba(243, 234, 209, 0.85)' : 'rgba(231, 240, 239, 0.6)'
    context.fillRect(Math.round(ground.x + dx), Math.round(ground.y + dy), 1, 1)
  }
}

// --- P42: bank klatek skoczka (dyskretny, bez ciÄ…gĹ‚ej rotacji proceduralnej) -

type JumperPose = 'gate' | 'inrun' | 'takeoff' | 'flight' | 'landingPrep' | 'outrun' | 'fall'

export const JUMPER_ART_VERSION = 'pkg008-jumper-frame-bank-1'
export const JUMPER_ART_SCALE = { skiPixels: 29, standingPixels: 22 } as const

/** BudĹĽet klatek na fazÄ™ â€” decyzja #7 (4 / 6-8 / 4+3 / 2-3 / 2-3). */
const FRAME_COUNT: Record<JumperPose, number> = {
  gate: 1,
  inrun: 3,
  takeoff: 4,
  flight: 7,
  // `landingPrep` Ĺ‚Ä…czy budĹĽet â€žprzygotowanieâ€ť (4) i â€žlÄ…dowanieâ€ť (3): faza
  // Contact jest w tym samym synchronicznym kroku nadpisywana na Outrun/Fall
  // (REPORT.md PKG-007 Â§4 #12) i nie jest obserwowalna przez renderer, wiÄ™c
  // trzy klatki â€žlÄ…dowaniaâ€ť to koĹ„cowe klatki podejĹ›cia w obrÄ™bie LandingPrep.
  landingPrep: 7,
  outrun: 3,
  fall: 2,
}

const RAD_PER_DEG = Math.PI / 180

function jumperPose(phase: string): JumperPose {
  if (phase === 'Fall' || phase === 'FallSettled') return 'fall'
  if (phase === 'GateGreen') return 'gate'
  if (phase === 'Inrun') return 'inrun'
  if (phase === 'Takeoff') return 'takeoff'
  if (phase === 'Flight') return 'flight'
  if (phase === 'LandingPrep') return 'landingPrep'
  return 'outrun'
}

function bucketAngle(valueRad: number, minDeg: number, maxDeg: number, count: number): { index: number; angleRad: number } {
  if (count <= 1) return { index: 0, angleRad: ((minDeg + maxDeg) / 2) * RAD_PER_DEG }
  const min = minDeg * RAD_PER_DEG
  const max = maxDeg * RAD_PER_DEG
  const t = Math.max(0, Math.min(1, (valueRad - min) / (max - min)))
  const index = Math.min(count - 1, Math.floor(t * count))
  const bucketWidth = (max - min) / count
  const angleRad = min + bucketWidth * (index + 0.5)
  return { index, angleRad }
}

/** Zwraca dyskretny numer klatki i reprezentatywny kÄ…t sylwetki dla tej klatki. */
function jumperFrame(phase: string, pitchRad: number, tick: number): { pose: JumperPose; frameIndex: number; angleRad: number } {
  const pose = jumperPose(phase)
  const count = FRAME_COUNT[pose]
  if (pose === 'inrun' || pose === 'outrun') {
    // Poza wybiciem/lotem/lÄ…dowaniem tor pochylenia jest prawie staĹ‚y â€” cykl
    // klatek idzie po ticku (powolne, powtarzalne koĹ‚ysanie), nie po kÄ…cie.
    return { pose, frameIndex: Math.floor(tick / 10) % count, angleRad: pitchRad }
  }
  if (pose === 'gate' || pose === 'fall') {
    const index = pose === 'fall' && phase === 'FallSettled' ? Math.min(count - 1, 1) : 0
    return { pose, frameIndex: index, angleRad: pitchRad }
  }
  const range: Record<'takeoff' | 'flight' | 'landingPrep', [number, number]> = {
    takeoff: [-40, 14],
    flight: [-26, 46],
    landingPrep: [-8, 42],
  }
  const [minDeg, maxDeg] = range[pose as 'takeoff' | 'flight' | 'landingPrep']
  const bucket = bucketAngle(pitchRad, minDeg, maxDeg, count)
  return { pose, frameIndex: bucket.index, angleRad: bucket.angleRad }
}

const FRAME_SIZE = 130
const FRAME_ANCHOR = { x: 65, y: 95 }
const frameCache = new Map<string, HTMLCanvasElement | OffscreenCanvas>()

function drawPixelHead(context: CanvasRenderingContext2D, x: number, y: number, fallen: boolean): void {
  const left = Math.round(x - 2)
  const top = Math.round(y - 2)
  context.fillStyle = '#07111f'
  context.fillRect(left, top + 1, 5, 4)
  context.fillStyle = fallen ? '#8c2f3e' : '#f1bd79'
  context.fillRect(left, top, 4, 1)
  context.fillRect(left, top + 1, 5, 2)
  context.fillRect(left, top + 3, 4, 1)
  context.fillStyle = '#286bc6'
  context.fillRect(left + 2, top + 1, 3, 1)
  context.fillStyle = '#e7f0ef'
  context.fillRect(left + 3, top + 1, 1, 1)
}

/** Rysuje jednÄ… klatkÄ™ banku w lokalnych wspĂłĹ‚rzÄ™dnych (stopy w `FRAME_ANCHOR`). */
function renderJumperFrame(pose: JumperPose, angleRad: number): HTMLCanvasElement | OffscreenCanvas | null {
  const canvas = typeof OffscreenCanvas === 'function'
    ? new OffscreenCanvas(FRAME_SIZE, FRAME_SIZE)
    : Object.assign(document.createElement('canvas'), { width: FRAME_SIZE, height: FRAME_SIZE })
  const context = canvas.getContext('2d') as CanvasRenderingContext2D | null
  if (!context) return null
  context.imageSmoothingEnabled = false

  const fallen = pose === 'fall'
  const feet = FRAME_ANCHOR
  const skiAngle = angleRad
  const ski = { x: Math.cos(skiAngle), y: -Math.sin(skiAngle) }
  const up = { x: ski.y, y: -ski.x }
  const skiHalf = JUMPER_ART_SCALE.skiPixels / 2
  const skiColor = fallen ? COLOR.red : '#f6cf69'
  // Skoczek stoi NA nartach, nie jest nimi przebity: caĹ‚a para leĹĽy pod
  // stopami (wzdĹ‚uĹĽ -up), body/nogi zaczynajÄ… siÄ™ dopiero nad niÄ….
  const skiRestX = feet.x - up.x * 2
  const skiRestY = feet.y - up.y * 2
  // V-style: w locie/wybiciu/przygotowaniu lÄ…dowania narty rozchodzÄ… siÄ™ pod
  // kÄ…tem od siebie (widoczne w SJ3 s16.gif); na ziemi (rozbieg/odjazd/belka)
  // leĹĽÄ… rĂłwnolegle obok siebie, jak na nartostradzie.
  const vSpreadRad = pose === 'flight' ? 0.30 : pose === 'takeoff' || pose === 'landingPrep' ? 0.14 : 0

  for (const side of [-1, 1] as const) {
    const spread = vSpreadRad * side
    const dir = { x: Math.cos(skiAngle + spread), y: -Math.sin(skiAngle + spread) }
    const lateral = 1.6 * side
    const fromX = skiRestX - dir.x * skiHalf * 0.35 + up.x * lateral
    const fromY = skiRestY - dir.y * skiHalf * 0.35 + up.y * lateral
    const toX = skiRestX + dir.x * skiHalf * 1.65 + up.x * lateral
    const toY = skiRestY + dir.y * skiHalf * 1.65 + up.y * lateral
    pixelLine(context, fromX, fromY, toX, toY, '#07111f', 2)
    pixelLine(context, fromX + dir.x, fromY + dir.y, toX, toY, skiColor, 1)
    context.fillStyle = '#f3ead1'
    context.fillRect(Math.round(toX - 1), Math.round(toY - 1), 2, 1)
  }

  const poseAngleOffset: Record<JumperPose, number> = {
    gate: 1.42,
    inrun: 0.73,
    takeoff: 1.08,
    flight: 0.43,
    landingPrep: 1.12,
    outrun: 1.34,
    fall: 0.18,
  }
  const bodyAngle = skiAngle + poseAngleOffset[pose]
  const body = { x: Math.cos(bodyAngle), y: -Math.sin(bodyAngle) }
  const hip = { x: feet.x + body.x * 4, y: feet.y + body.y * 4 + up.y * 1 }
  const shoulder = { x: hip.x + body.x * 9, y: hip.y + body.y * 9 }
  const head = { x: shoulder.x + body.x * 4, y: shoulder.y + body.y * 4 }

  for (const shift of [-2, 2]) {
    const foot = { x: feet.x + ski.x * shift, y: feet.y + ski.y * shift }
    pixelLine(context, foot.x - ski.x, foot.y - ski.y, foot.x + ski.x * 1.5, foot.y + ski.y * 1.5, '#07111f', 2)
    pixelLine(context, foot.x, foot.y, hip.x + ski.x * shift * 0.22, hip.y + ski.y * shift * 0.22, fallen ? '#8c2f3e' : '#244b75', 2)
  }

  pixelLine(context, hip.x, hip.y, shoulder.x, shoulder.y, '#07111f', 4)
  pixelLine(context, hip.x, hip.y, shoulder.x, shoulder.y, fallen ? '#8c2f3e' : '#d64d53', 3)
  const bib = { x: hip.x + body.x * 5, y: hip.y + body.y * 5 }
  context.fillStyle = '#e7f0ef'
  context.fillRect(Math.round(bib.x - 1), Math.round(bib.y - 1), 3, 3)
  context.fillStyle = '#286bc6'
  context.fillRect(Math.round(bib.x), Math.round(bib.y), 1, 1)

  const armAngle = bodyAngle + (pose === 'flight' ? -0.35 : pose === 'landingPrep' ? 0.72 : -0.62)
  const arm = { x: Math.cos(armAngle), y: -Math.sin(armAngle) }
  const armStart = { x: shoulder.x - body.x * 2, y: shoulder.y - body.y * 2 }
  const elbow = { x: armStart.x + arm.x * 5, y: armStart.y + arm.y * 5 }
  const hand = { x: elbow.x + arm.x * 4, y: elbow.y + arm.y * 4 }
  pixelLine(context, armStart.x, armStart.y, elbow.x, elbow.y, '#07111f', 3)
  pixelLine(context, armStart.x, armStart.y, elbow.x, elbow.y, fallen ? '#8c2f3e' : '#f3ead1', 2)
  pixelLine(context, elbow.x, elbow.y, hand.x, hand.y, '#07111f', 2)
  pixelLine(context, elbow.x, elbow.y, hand.x, hand.y, fallen ? '#8c2f3e' : '#d64d53', 2)
  drawPixelHead(context, head.x, head.y, fallen)

  return canvas
}

function jumperFrameBitmap(pose: JumperPose, frameIndex: number, angleRad: number): HTMLCanvasElement | OffscreenCanvas | null {
  const key = `${pose}:${frameIndex}`
  const cached = frameCache.get(key)
  if (cached) return cached
  const bitmap = renderJumperFrame(pose, angleRad)
  if (bitmap) frameCache.set(key, bitmap)
  return bitmap
}

/** Blituje klatkÄ™ z banku (bez rotacji/skalowania w locie â€” kÄ…t jest juĹĽ zapieczony w bitmapie). */
function drawProductionJumper(context: CanvasRenderingContext2D, view: WorldView, actor: SceneActor): void {
  const { pose, frameIndex, angleRad } = jumperFrame(actor.phase, actor.pitchRad, actor.tick)
  const bitmap = jumperFrameBitmap(pose, frameIndex, angleRad)
  if (!bitmap) return
  const feet = view.toScreen(actor.position)
  context.drawImage(bitmap, Math.round(feet.x - FRAME_ANCHOR.x), Math.round(feet.y - FRAME_ANCHOR.y))
}

function decimal(value: number, digits = 1): string {
  return value.toFixed(digits).replace('.', ',')
}

function points(tenths: number): string {
  return decimal(tenths / 10)
}

function signedPoints(tenths: number): string {
  return `${tenths >= 0 ? '+' : ''}${points(tenths)}`
}

function compensationColor(tenths: number): string {
  if (tenths > 0) return COLOR.green
  if (tenths < 0) return COLOR.red
  return COLOR.snowShade
}

function distance(halfMeters: number): string {
  return decimal(halfMeters / 2)
}

