  // biaĹ‚ego pasa (â€žwbite w ziemiÄ™"). Podnosimy caĹ‚y blit tak, ĹĽeby spody
  // nart spoczÄ™Ĺ‚y na GĂ“RNEJ krawÄ™dzi pasa: 5 px na zeskoku/odjeĹşdzie,
  // 4 px na rozbiegu/belce. Fazy powietrzne bez korekty.
  const groundLift: Record<JumperPose, number> = {
