export function pixelLine(
  context: CanvasRenderingContext2D,
  fromX: number,
  fromY: number,
  toX: number,
  toY: number,
  color: string,
  thickness = 1,
): void {
  let x0 = Math.round(fromX)
  let y0 = Math.round(fromY)
  const x1 = Math.round(toX)
  const y1 = Math.round(toY)
  const dx = Math.abs(x1 - x0)
  const sx = x0 < x1 ? 1 : -1
  const dy = -Math.abs(y1 - y0)
  const sy = y0 < y1 ? 1 : -1
  let error = dx + dy
  const offset = Math.floor(thickness / 2)
  context.fillStyle = color
  while (true) {
    context.fillRect(x0 - offset, y0 - offset, thickness, thickness)
    if (x0 === x1 && y0 === y1) break
    const twiceError = error * 2
    if (twiceError >= dy) {
      error += dy
      x0 += sx
    }
    if (twiceError <= dx) {
      error += dx
      y0 += sy
    }
  }
}

/** Kolejne segmenty Bresenhama zamiast jednej antyaliasowanej Ĺ›cieĹĽki krzywej. */
function pixelPolyline(
  context: CanvasRenderingContext2D,
  points: readonly Vec2[],
  color: string,
  thickness: number,
): void {
  for (let index = 0; index + 1 < points.length; index += 1) {
    const a = points[index]
    const b = points[index + 1]
    if (!a || !b) continue
    pixelLine(context, a.x, a.y, b.x, b.y, color, thickness)
  }
}

/** Rasteryzacja skanliniowa (even-odd): jedyny sposĂłb wypeĹ‚nienia wielokÄ…ta bez AA. */
export function fillPixelPolygon(
  context: CanvasRenderingContext2D,
  color: string,
  points: readonly (readonly [number, number])[],
): void {
  if (points.length < 3) return
  let minY = Infinity
  let maxY = -Infinity
  for (const [, y] of points) {
    if (y < minY) minY = y
    if (y > maxY) maxY = y
  }
  const top = Math.max(-8, Math.floor(minY))
  const bottom = Math.min(VIEW_HEIGHT + 8, Math.ceil(maxY))
  context.fillStyle = color
  for (let y = top; y < bottom; y += 1) {
    const scanY = y + 0.5
    const xs: number[] = []
    for (let index = 0; index < points.length; index += 1) {
      const a = points[index] as readonly [number, number]
      const b = points[(index + 1) % points.length] as readonly [number, number]
      const [x1, y1] = a
      const [x2, y2] = b
      if (y1 === y2) continue
      if (scanY < Math.min(y1, y2) || scanY >= Math.max(y1, y2)) continue
      const t = (scanY - y1) / (y2 - y1)
      xs.push(x1 + t * (x2 - x1))
    }
    xs.sort((a, b) => a - b)
    for (let index = 0; index + 1 < xs.length; index += 2) {
      const xStart = Math.round(xs[index] as number)
      const xEnd = Math.round(xs[index + 1] as number)
      if (xEnd > xStart) context.fillRect(xStart, y, xEnd - xStart, 1)
    }
  }
}

/** Zgrubna elipsa jako wielokÄ…t do `fillPixelPolygon` â€” bez krzywych Beziera. */
function ellipsePoints(cx: number, cy: number, halfWidth: number, halfHeight: number, segments = 12): Array<[number, number]> {
  const points: Array<[number, number]> = []
  for (let index = 0; index < segments; index += 1) {
    const angle = (index / segments) * Math.PI * 2
    points.push([cx + Math.cos(angle) * halfWidth, cy + Math.sin(angle) * halfHeight])
  }
  return points
}

// --- Font bitmapowy wszÄ™dzie: adapter na starych wywoĹ‚aniach label() -------

function sizeToScale(size: number): number {
  return size >= 18 ? 3 : size >= 13 ? 2 : 1
}

function currentAlign(context: CanvasRenderingContext2D): PixelTextAlign {
  return context.textAlign === 'right' ? 'right' : context.textAlign === 'center' ? 'center' : 'left'
}

function label(context: CanvasRenderingContext2D, text: string, x: number, y: number, color: string, size = 13): void {
  const scale = sizeToScale(size)
  drawPixelText(context, text, x, y - 7 * scale, color, scale, currentAlign(context))
}

private applyLandingSelection(input: TickInput): void {
  // Przy T i R w tym samym ticku wygrywa R jako bezpieczniejszy wariant.
  const wantsParallel = input.pressed.includes('parallel')
  const wantsTelemark = input.pressed.includes('telemark')
