      boot: [0, 1.5], knee: [6, 4.6], hip: [-1.6, 6.2], chest: [5.4, 7.9], head: [9.4, 7.7],
      elbow: [0, 7.2], hand: [-4.2, 6.6], vTip: 0,
    },
