      boot: [0, 1.5], knee: [4.5, 6.6], hip: [3.5, 10.4], chest: [11, 13.2], head: [14.8, 13.8],
      elbow: [5.5, 12.2], hand: [1.2, 11.2], vTip: 1,
    },
  ],
  // Lot: ciaĹ‚o wznosi siÄ™ do przodu pod ~25Â° do nart (jak SJ3 s16) â€” miÄ™dzy
  // nartÄ… a biodrem widaÄ‡ tĹ‚o, gĹ‚owa wysoko z przodu, rÄ™ce dociĹ›niÄ™te do ciaĹ‚a.
  flight: [
    {
      skiFrom: -8, skiTo: 21,
      boot: [0, 1.5], knee: [5, 3.8], hip: [9.4, 6], chest: [15.4, 9.2], head: [19, 10.8],
