      boot: [4, 1.5], knee: [6.5, 6.2], backBoot: [-5.5, 1.5], backKnee: [-3.5, 5.2],
      hip: [0.5, 10.2], chest: [3, 15.4], head: [5.6, 18],
      elbow: [7.4, 16.6], hand: [11.4, 17.4],
      farElbow: [-1.4, 16.2], farHand: [-5.4, 16.8],
      vTip: 0,
    },
  ],
  // Odjazd: sylwetka stojÄ…ca (JUMPER_ART_SCALE.standingPixels), rÄ™ce wzdĹ‚uĹĽ ciaĹ‚a.
  outrun: [
    {
      skiFrom: -12, skiTo: 17,
