  fall: [
    {
      skiFrom: -10, skiTo: 19,
      boot: [0, 1.5], knee: [-4.5, 3.4], hip: [-9, 4], chest: [-14.4, 5.2], head: [-17.6, 6.6],
      elbow: [-12, 7.4], hand: [-8.4, 8.6],
    },
    {
      skiFrom: -10, skiTo: 19,
      boot: [0, 1.5], knee: [-5, 2.6], hip: [-9.8, 2.8], chest: [-15.4, 3.4], head: [-18.6, 4.4],
      elbow: [-13, 5.2], hand: [-9.6, 6],
    },
  ],
}

function poseShape(pose: JumperPose, frameIndex: number): PoseShape {
  const keys = POSE_KEYS[pose]
  const first = keys[0] as PoseShape
  if (keys.length < 2) return first
  const count = FRAME_COUNT[pose]
  const raw = count <= 1 ? 0 : frameIndex / (count - 1)
  // Rozbieg i odjazd nie â€žprzechodzÄ…" miÄ™dzy pozami tylko koĹ‚yszÄ… siÄ™ tam i
  // z powrotem â€” stÄ…d trĂłjkÄ…tny przebieg zamiast liniowego.
  const cyclic = pose === 'inrun' || pose === 'outrun' || pose === 'gate'
  const t = cyclic ? 1 - Math.abs(raw * 2 - 1) : raw
  const span = keys.length - 1
  const scaled = Math.min(span - 0.0001, Math.max(0, t * span))
  const index = Math.floor(scaled)
  const a = keys[index] as PoseShape
  const b = keys[index + 1] as PoseShape
  return blendPose(a, b, scaled - index)
}

/** WypeĹ‚niony czworokÄ…t â€žkoĹ„czyny": odcinek aâ†’b o zadanych pĂłĹ‚szerokoĹ›ciach. */
function limbQuad(
  context: CanvasRenderingContext2D,
  toScreen: (u: number, v: number) => readonly [number, number],
  a: SkiPoint,
  b: SkiPoint,
  halfA: number,
  halfB: number,
  color: string,
): void {
  const dx = b[0] - a[0]
  const dy = b[1] - a[1]
  const length = Math.hypot(dx, dy) || 1
  const nx = -dy / length
  const ny = dx / length
  fillPixelPolygon(context, color, [
    toScreen(a[0] + nx * halfA, a[1] + ny * halfA),
    toScreen(b[0] + nx * halfB, b[1] + ny * halfB),
    toScreen(b[0] - nx * halfB, b[1] - ny * halfB),
    toScreen(a[0] - nx * halfA, a[1] - ny * halfA),
  ])
}

/** Narta: dĹ‚uga cienka bryĹ‚a leĹĽÄ…ca na vâ‰�0, z lekko uniesionym czubkiem. */
function drawSki(
  context: CanvasRenderingContext2D,
  toScreen: (u: number, v: number) => readonly [number, number],
  from: number,
  to: number,
  offsetV: number,
  vTip: number,
  color: string,
): void {
  const tipLift = 0.9
  fillPixelPolygon(context, color, [
    toScreen(from, offsetV - 0.5),
    toScreen(from + 1.5, offsetV - 0.5 + tipLift * 0.6),
    toScreen(to - 2, offsetV + 0.5 + vTip * 0.5),
    toScreen(to, offsetV + 0.2 + tipLift + vTip),
    toScreen(to, offsetV + 1.2 + tipLift + vTip),
    toScreen(to - 2, offsetV + 1.5 + vTip * 0.5),
    toScreen(from + 1.5, offsetV + 0.5 + tipLift * 0.6),
    toScreen(from, offsetV + 0.5),
  ])
}

/** GĹ‚owa w kasku: jasna skorupa, twarz z przodu, ciemny wizjer na czubku nosa. */
function drawHelmet(
  context: CanvasRenderingContext2D,
  toScreen: (u: number, v: number) => readonly [number, number],
  head: SkiPoint,
  chest: SkiPoint,
  fallen: boolean,
): void {
  const dx = head[0] - chest[0]
  const dy = head[1] - chest[1]
  const length = Math.hypot(dx, dy) || 1
  const fx = dx / length
  const fy = dy / length
  const shell: Array<readonly [number, number]> = []
  for (let index = 0; index < 10; index += 1) {
    const angle = (index / 10) * Math.PI * 2
    shell.push(toScreen(head[0] + Math.cos(angle) * 2.7, head[1] + Math.sin(angle) * 2.5))
  }
  fillPixelPolygon(context, fallen ? SUIT.shade : SUIT.light, shell)
  const face = toScreen(head[0] + fx * 1.6 - fy * -0.9, head[1] + fy * 1.6 - fx * 0.9)
  context.fillStyle = fallen ? SUIT.shade : SUIT.skin
  context.fillRect(Math.round(face[0]) - 1, Math.round(face[1]) - 1, 2, 2)
  const visor = toScreen(head[0] + fx * 2.4, head[1] + fy * 2.4)
  context.fillStyle = SUIT.outline
  context.fillRect(Math.round(visor[0]), Math.round(visor[1]), 1, 1)
}

/** 1-pikselowy obrys z maski alfa â€” sylwetka czyta siÄ™ na Ĺ›niegu i na niebie. */
function outlineSilhouette(context: CanvasRenderingContext2D): void {
  const image = context.getImageData(0, 0, FRAME_SIZE, FRAME_SIZE)
  const alpha = image.data
  const solid = new Uint8Array(FRAME_SIZE * FRAME_SIZE)
  for (let index = 0; index < solid.length; index += 1) {
    solid[index] = (alpha[index * 4 + 3] as number) > 0 ? 1 : 0
  }
  context.fillStyle = SUIT.outline
  for (let y = 0; y < FRAME_SIZE; y += 1) {
    for (let x = 0; x < FRAME_SIZE; x += 1) {
      const here = y * FRAME_SIZE + x
      if (solid[here]) continue
      const touches =
        (x > 0 && solid[here - 1]) ||
        (x + 1 < FRAME_SIZE && solid[here + 1]) ||
        (y > 0 && solid[here - FRAME_SIZE]) ||
        (y + 1 < FRAME_SIZE && solid[here + FRAME_SIZE])
      if (touches) context.fillRect(x, y, 1, 1)
    }
  }
}

/** Rysuje jednÄ… klatkÄ™ banku w lokalnych wspĂłĹ‚rzÄ™dnych (styk buta w `FRAME_ANCHOR`). */
function renderJumperFrame(pose: JumperPose, frameIndex: number, angleRad: number): HTMLCanvasElement | OffscreenCanvas | null {
  const canvas = typeof OffscreenCanvas === 'function'
    ? new OffscreenCanvas(FRAME_SIZE, FRAME_SIZE)
    : Object.assign(document.createElement('canvas'), { width: FRAME_SIZE, height: FRAME_SIZE })
  const context = canvas.getContext('2d') as CanvasRenderingContext2D | null
  if (!context) return null
  context.imageSmoothingEnabled = false

  const fallen = pose === 'fall'
  const shape = poseShape(pose, frameIndex)
  const cos = Math.cos(angleRad)
  const sin = Math.sin(angleRad)
  // Narta = (cos, -sin), pion sylwetki = (-sin, -cos): ta sama konwencja co
  // reszta renderera (ekranowe Y roĹ›nie w dĂłĹ‚).
  const toScreen = (u: number, v: number): readonly [number, number] => [
    FRAME_ANCHOR.x + u * cos - v * sin,
    FRAME_ANCHOR.y - u * sin - v * cos,
  ]

  const main = fallen ? SUIT.shade : SUIT.main
  const shade = fallen ? '#6d2430' : SUIT.shade
  const light = fallen ? SUIT.shade : SUIT.light
  const vTip = shape.vTip ?? 0

  // 1. Narty â€” najpierw dalsza (ciemniejsza, 1 px wyĹĽej, czubek rozwarty o
  //    `vTip`): z boku V jest prawie niewidoczne, wiÄ™c zostaje z niego wÄ…ski
  //    klin przy czubku, a nie druga kreska.
  if (shape.backSkiFrom !== undefined && shape.backSkiTo !== undefined) {
    drawSki(context, toScreen, shape.backSkiFrom, shape.backSkiTo, 0, 0, SUIT.skiFar)
  } else {
    drawSki(context, toScreen, shape.skiFrom, shape.skiTo, 1, vTip, SUIT.skiFar)
  }
  drawSki(context, toScreen, shape.skiFrom, shape.skiTo, 0, 0, fallen ? SUIT.shade : SUIT.skiNear)

  // 2. Dalsza noga (telemark) i dalsza rÄ™ka â€” ciemniejsze, ĹĽeby daĹ‚y gĹ‚Ä™biÄ™.
  if (shape.backBoot && shape.backKnee) {
    limbQuad(context, toScreen, shape.hip, shape.backKnee, 2.2, 1.8, shade)
    limbQuad(context, toScreen, shape.backKnee, shape.backBoot, 1.8, 1.4, shade)
    const backBoot = toScreen(shape.backBoot[0], shape.backBoot[1])
    context.fillStyle = SUIT.outline
    context.fillRect(Math.round(backBoot[0]) - 1, Math.round(backBoot[1]) - 1, 3, 2)
  }
  const farElbow = shape.farElbow ?? shape.elbow
  const farHand = shape.farHand ?? shape.hand
  limbQuad(context, toScreen, shape.chest, farElbow, 1.5, 1.2, shade)
  limbQuad(context, toScreen, farElbow, farHand, 1.2, 1, shade)

  // 3. Noga bliĹĽsza: udo i podudzie jako bryĹ‚y (kreska tonÄ™Ĺ‚a w narcie).
  limbQuad(context, toScreen, shape.hip, shape.knee, 2.4, 1.9, main)
  limbQuad(context, toScreen, shape.knee, shape.boot, 1.9, 1.4, main)

  // 4. But z wiÄ…zaniem â€” styk z nartÄ… musi byÄ‡ jednym wyraĹşnym, ciemnym blokiem.
  const boot = toScreen(shape.boot[0], shape.boot[1])
  context.fillStyle = SUIT.outline
  context.fillRect(Math.round(boot[0]) - 2, Math.round(boot[1]) - 1, 4, 2)

  // 5. TuĹ‚Ăłw jako bryĹ‚a + jasny grzbiet po stronie â€žod nart" (SJ3: jasne plecy).
  limbQuad(context, toScreen, shape.hip, shape.chest, 2.8, 3, main)
  const backDx = shape.chest[0] - shape.hip[0]
  const backDy = shape.chest[1] - shape.hip[1]
  const backLength = Math.hypot(backDx, backDy) || 1
  const nx = -backDy / backLength
  const ny = backDx / backLength
  limbQuad(
    context,
    toScreen,
    [shape.hip[0] + nx * 1.5, shape.hip[1] + ny * 1.5],
    [shape.chest[0] + nx * 1.6, shape.chest[1] + ny * 1.6],
    1.2,
    1.3,
    light,
  )

  // 6. RÄ™ka bliĹĽsza: jasny rÄ™kaw wzdĹ‚uĹĽ tuĹ‚owia, dĹ‚oĹ„ w kolorze skĂłry.
  limbQuad(context, toScreen, shape.chest, shape.elbow, 1.6, 1.3, light)
  limbQuad(context, toScreen, shape.elbow, shape.hand, 1.3, 1, light)
  const hand = toScreen(shape.hand[0], shape.hand[1])
  context.fillStyle = fallen ? SUIT.shade : SUIT.skin
  context.fillRect(Math.round(hand[0]) - 1, Math.round(hand[1]) - 1, 2, 2)

  drawHelmet(context, toScreen, shape.head, shape.chest, fallen)
  outlineSilhouette(context)

  return canvas
}

function jumperFrameBitmap(
  pose: JumperPose,
  frameIndex: number,
  angleIndex: number,
  angleRad: number,
): HTMLCanvasElement | OffscreenCanvas | null {
  const key = `${pose}:${frameIndex}:${angleIndex}`
  const cached = frameCache.get(key)
  if (cached) return cached
  const bitmap = renderJumperFrame(pose, frameIndex, angleRad)
  if (bitmap) frameCache.set(key, bitmap)
  return bitmap
}

/** Blituje klatkÄ™ z banku (bez rotacji/skalowania w locie â€” kÄ…t jest juĹĽ zapieczony w bitmapie). */
function drawProductionJumper(context: CanvasRenderingContext2D, view: WorldView, actor: SceneActor): void {
  const groundY = actor.hill.surfaceYAtX(actor.position.x)
  const heightAboveSurface = Math.max(0, actor.position.y - groundY)
  const { pose, frameIndex, angleIndex, angleRad } = jumperFrame(
    actor.phase,
    actor.pitchRad,
    actor.tick,
    heightAboveSurface,
  )
  const bitmap = jumperFrameBitmap(pose, frameIndex, angleIndex, angleRad)
  if (!bitmap) return
  const feet = view.toScreen(actor.position)
  // Kotwica fizyki leĹĽy na MATEMATYCZNEJ powierzchni, a widoczny pas Ĺ›niegu
  // rysuje siÄ™ wyĹ›rodkowanym obrysem â€” bez korekty spody nart tonÄ™Ĺ‚yby w
  // poĹ‚owie biaĹ‚ego pasa (â€žwbite w ziemiÄ™"). Podnosimy blit tak, ĹĽeby narta
  // spoczÄ™Ĺ‚a na GĂ“RNEJ krawÄ™dzi pasa, i wygaszamy korektÄ™ wraz z odrywaniem
  // siÄ™ od zbocza, ĹĽeby przy wybiciu i lÄ…dowaniu nie byĹ‚o przeskoku.
  const groundLift: Record<JumperPose, number> = {
    gate: 4,
    inrun: 4,
    takeoff: 4,
    flight: 5,
    landingPrep: 5,
    outrun: 5,
    fall: 5,
  }
  const lift = groundLift[pose] * Math.max(0, 1 - heightAboveSurface)
  context.drawImage(bitmap, Math.round(feet.x - FRAME_ANCHOR.x), Math.round(feet.y - FRAME_ANCHOR.y - lift))
}

