// --- P42 runda â€žĹ›wieĹĽe oczy": sylwetka budowana z bryĹ‚, nie z kresek --------
//
// Diagnoza starego banku (patrz dowody `pkg008-crop-skoczek-*.png`): wszystko
// wychodziĹ‚o z JEDNEGO punktu (`feet`) i byĹ‚o rysowane 2-3-pikselowymi liniami
// pod niemal tym samym kÄ…tem co narta, wiÄ™c narta przechodziĹ‚a przez tuĹ‚Ăłw i
// caĹ‚oĹ›Ä‡ czytaĹ‚a siÄ™ jako jedna ukoĹ›na kreska. Referencja (SJ3 `s0A` klatka 1,
// `s16`) robi to inaczej i to jest wzorzec tej przebudowy:
//
//   1. narta to CIENKA, JASNA linia leĹĽÄ…ca na Ĺ›niegu, wystajÄ…ca daleko przed
//      i za sylwetkÄ™ â€” pod ciaĹ‚em, nigdy przez nie;
//   2. ciaĹ‚o to ZWARTA BRYĹ�A nad nartÄ… (wypeĹ‚nione czworokÄ…ty koĹ„czyn, nie
//      kreski), z tĹ‚em widocznym miÄ™dzy nartÄ… a biodrem;
//   3. na rozbiegu tuĹ‚Ăłw leĹĽy prawie rĂłwnolegle do nart, biodra z tyĹ‚u, kolana
//      przed butem, gĹ‚owa nisko z przodu â€” gĹ‚Ä™boki kuc, nie postawa stojÄ…ca;
//   4. rÄ™ce idÄ… WZDĹ�UĹ» tuĹ‚owia do tyĹ‚u, dĹ‚onie przy biodrach (jedyny wyjÄ…tek to
//      lÄ…dowanie: rÄ™ce na zewnÄ…trz dla rĂłwnowagi â€” `real-telemark-landing-side.jpg`);
//   5. caĹ‚oĹ›Ä‡ dostaje 1-pikselowy ciemny obrys z maski alfa, ĹĽeby sylwetka
//      czytaĹ‚a siÄ™ i na Ĺ›niegu, i na nocnym niebie (dyscyplina kontrastu DSJ2).

const FRAME_SIZE = 72
const FRAME_ANCHOR = { x: 36, y: 46 }
const frameCache = new Map<string, HTMLCanvasElement | OffscreenCanvas>()

/** Barwy sylwetki â€” wyĹ‚Ä…cznie odcienie juĹĽ obecne w palecie pakietu. */
const SUIT = {
  outline: '#07111f',
  main: '#d64d53',
  shade: '#8c2f3e',
  light: '#f3ead1',
  skin: '#f1bd79',
  skiNear: '#f6cf69',
  skiFar: '#c1903f',
} as const

/** Punkt w ukĹ‚adzie narty: `u` wzdĹ‚uĹĽ nart (w przĂłd), `v` prostopadle w gĂłrÄ™. */
type SkiPoint = readonly [number, number]

/**
 * Jedna poza w ukĹ‚adzie narty. Wszystkie wartoĹ›ci sÄ… w pikselach bufora 480Ă—270,
 * liczone od punktu styku buta z nartÄ… (0, 0) â€” dlatego â€žnarta pod ciaĹ‚em" jest
 * wĹ‚asnoĹ›ciÄ… danych, a nie szczÄ™Ĺ›liwym trafem rysowania.
 */
type PoseShape = {
  readonly skiFrom: number
  readonly skiTo: number
  readonly boot: SkiPoint
  readonly knee: SkiPoint
  readonly hip: SkiPoint
  readonly chest: SkiPoint
  readonly head: SkiPoint
  readonly elbow: SkiPoint
  readonly hand: SkiPoint
  /** RÄ™ka dalsza â€” domyĹ›lnie towarzyszy bliĹĽszej; przy lÄ…dowaniu idzie w tyĹ‚. */
  readonly farElbow?: SkiPoint
  readonly farHand?: SkiPoint
  /** Telemark: druga noga i druga narta przesuniÄ™te w tyĹ‚. */
  readonly backBoot?: SkiPoint
  readonly backKnee?: SkiPoint
  readonly backSkiFrom?: number
  readonly backSkiTo?: number
  /** Rozwarcie V na czubku dalszej narty (px). 0 = narty rĂłwnolegĹ‚e w torach. */
  readonly vTip?: number
}

function lerpPoint(a: SkiPoint, b: SkiPoint, t: number): SkiPoint {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]
}

function lerpOptional(a: SkiPoint | undefined, b: SkiPoint | undefined, t: number): SkiPoint | undefined {
  if (!a || !b) return t < 0.5 ? a : b
  return lerpPoint(a, b, t)
}

function lerpNumber(a: number | undefined, b: number | undefined, t: number): number | undefined {
  if (a === undefined || b === undefined) return t < 0.5 ? a : b
  return a + (b - a) * t
}

function blendPose(a: PoseShape, b: PoseShape, t: number): PoseShape {
  return {
    skiFrom: a.skiFrom + (b.skiFrom - a.skiFrom) * t,
    skiTo: a.skiTo + (b.skiTo - a.skiTo) * t,
    boot: lerpPoint(a.boot, b.boot, t),
    knee: lerpPoint(a.knee, b.knee, t),
    hip: lerpPoint(a.hip, b.hip, t),
    chest: lerpPoint(a.chest, b.chest, t),
    head: lerpPoint(a.head, b.head, t),
    elbow: lerpPoint(a.elbow, b.elbow, t),
    hand: lerpPoint(a.hand, b.hand, t),
    farElbow: lerpOptional(a.farElbow, b.farElbow, t),
    farHand: lerpOptional(a.farHand, b.farHand, t),
    backBoot: lerpOptional(a.backBoot, b.backBoot, t),
    backKnee: lerpOptional(a.backKnee, b.backKnee, t),
    backSkiFrom: lerpNumber(a.backSkiFrom, b.backSkiFrom, t),
    backSkiTo: lerpNumber(a.backSkiTo, b.backSkiTo, t),
    vTip: lerpNumber(a.vTip, b.vTip, t),
  }
}

/**
 * Klatki kluczowe pozy; `FRAME_COUNT` klatek powstaje przez interpolacjÄ™ miÄ™dzy
 * nimi (pĹ‚ynniej niĹĽ 4 klatki SJ3, a dane zostajÄ… czytelne).
 */
const POSE_KEYS: Record<JumperPose, readonly PoseShape[]> = {
  // Belka: pĂłĹ‚kuc â€” wyĹĽej niĹĽ na rozbiegu, ĹĽeby przejĹ›cie do kuca byĹ‚o widoczne.
  gate: [{
    skiFrom: -12, skiTo: 17,
