  }],
  // Rozbieg: gĹ‚Ä™boki kuc â€” tuĹ‚Ăłw prawie rĂłwnolegle do nart, biodra za kolanami,
  // gĹ‚owa nisko z przodu, dĹ‚onie przy biodrach z tyĹ‚u (usterka #1 i #2).
  inrun: [
    {
      skiFrom: -12, skiTo: 17,
      boot: [0, 1.5], knee: [6, 4.6], hip: [-1.6, 6.2], chest: [5.4, 7.9], head: [9.4, 7.7],
      elbow: [0, 7.2], hand: [-4.2, 6.6],
    },
    {
