      boot: [0, 1.5], knee: [6.2, 5.1], hip: [-1.4, 6.7], chest: [5.8, 8.5], head: [9.8, 8.3],
      elbow: [0.3, 7.8], hand: [-3.9, 7.2],
    },
  ],
  // Wybicie: z kuca w wyprost do przodu; rÄ™ce nadal wzdĹ‚uĹĽ ciaĹ‚a (technika V).
  takeoff: [
    {
      skiFrom: -11, skiTo: 18,
      boot: [0, 1.5], knee: [6, 4.6], hip: [-1.6, 6.2], chest: [5.4, 7.9], head: [9.4, 7.7],
      elbow: [0, 7.2], hand: [-4.2, 6.6], vTip: 0,
