import { expect, test, type Page } from '@playwright/test'

type RuntimeDebug = { paused: boolean; pauseReason: string; journal: string[] }

/**
 * PÄ™tla 120 Hz celowo przechodzi w pauzÄ™, gdy klatka przekroczy limit
 * nadrabiania. Pod obciÄ…ĹĽeniem automatyzacji zdarza siÄ™ to takĹĽe tuĹĽ po
 * wznowieniu, dlatego wznawiamy do skutku i sprawdzamy, ĹĽe powodem jest
 * wyĹ‚Ä…cznie ten udokumentowany mechanizm, a nie inny bĹ‚Ä…d stanu.
 */
async function resumeIfPaused(page: Page, attempts = 8): Promise<void> {
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    const state = await page.evaluate(() => (
      window as unknown as { __retroDebugSnapshot: () => RuntimeDebug }
    ).__retroDebugSnapshot())
    if (!state.paused) return
    if (attempt > 0) {
      expect(state.pauseReason).toBe('zbyt dĹ‚uga przerwa klatki')
    }
    await page.keyboard.press('Enter')
  }
}

