/**
 * P42 runda 6 â€” kalibracja skoczni i lotu wobec danych rzeczywistych.
 *
 * Test pilnuje WIELKOĹšCI OBSERWOWALNYCH, nie staĹ‚ych modelu: prÄ™dkoĹ›ci na
 * progu, rozrzutu dĹ‚ugoĹ›ci miÄ™dzy belkami, czasu lotu i gradientu umiejÄ™tnoĹ›ci.
 * DziÄ™ki temu wolno zmieniaÄ‡ `referenceAreaSquareMeters`, `dragScale` czy
 * krzywÄ… wspĂłĹ‚czynnikĂłw, dopĂłki gra zachowuje siÄ™ jak prawdziwa skocznia
 * K120/HS134. Odniesienia liczbowe: FIS Jumping Hills Construction Norm 2018
 * oraz certyfikat skoczni WisĹ‚a Malinka HS134 (przebudowa 2023).
 */

import { describe, expect, it } from 'vitest'
import { buildHill } from '../src/simulation/technicalHill'
import { runJump } from './support/jumpHarness'
import { compensationFactors, probe } from './support/tuneProbe'

const hill = buildHill()

describe('P42 â€” geometria rozbiegu wobec normy FIS', () => {
  it('trzyma kÄ…ty, dĹ‚ugoĹ›ci i wysokoĹ›Ä‡ progu w granicach normy', () => {
    const spec = hill.spec
    const keyframes = spec.inrun.keyframes
    const first = keyframes[0]
    const last = keyframes[keyframes.length - 1]
    expect(first?.slopeDeg).toBe(35)
    // Norma Â§6.4: najazd nie powyĹĽej 37Â°, zalecane nie powyĹĽej 35Â°, a dla
    // skoczni o w â‰Ą 90 nie mniej niĹĽ 30Â°.
    expect(first?.slopeDeg ?? 0).toBeLessThanOrEqual(35)
    expect(first?.slopeDeg ?? 0).toBeGreaterThanOrEqual(30)

    // Norma Â§4.1: Î± = w/30 + 7,4 z zakresu w/30 + 6,9 â€¦ w/30 + 7,9.
    const w = spec.kPointMeters
    expect(last?.slopeDeg ?? 0).toBeGreaterThanOrEqual(w / 30 + 6.9)
    expect(last?.slopeDeg ?? 0).toBeLessThanOrEqual(w / 30 + 7.9)

    // Certyfikat WisĹ‚a Malinka HS134: e 94,35 m, t 6,71 m, s 3,03 m.
    expect(spec.inrun.lengthMeters).toBeCloseTo(94.35, 2)
    expect(spec.inrun.lengthMeters - (keyframes[keyframes.length - 2]?.distanceMeters ?? 0)).toBeCloseTo(6.71, 2)
    expect(spec.tableClearanceMeters).toBeCloseTo(3.03, 2)
  })

  it('rozstawia belki poniĹĽej normowego limitu 0,40 m rĂłĹĽnicy wysokoĹ›ci', () => {
    const gates = hill.spec.inrun.gates
    const spacing = (gates[1]?.inrunLengthMeters ?? 0) - (gates[0]?.inrunLengthMeters ?? 0)
    const dropMeters = spacing * Math.sin((35 * Math.PI) / 180)
    expect(spacing).toBeGreaterThan(0)
    expect(dropMeters).toBeLessThanOrEqual(0.4)
  })

  it('daje prÄ™dkoĹ›Ä‡ na progu z zakresu duĹĽej skoczni', () => {
    // Certyfikat WisĹ‚y podaje 92,5 km/h; dopuszczamy realny rozrzut belek.
    for (const gate of [1, 8, 12]) {
      const speed = probe(gate).tableSpeedKmh
      expect(speed).toBeGreaterThan(87)
      expect(speed).toBeLessThan(96)
    }
    expect(probe(12).tableSpeedKmh).toBeGreaterThan(probe(1).tableSpeedKmh)
  })
})

describe('P42 â€” lot wobec skoczni K120/HS134', () => {
  it('ukĹ‚ada dĹ‚ugoĹ›ci wokĂłĹ‚ punktu K i roĹ›nie monotonicznie z belkÄ…', () => {
    const distances = hill.spec.inrun.gates.map((gate) => probe(gate.number).distanceMeters ?? 0)
    for (let index = 1; index < distances.length; index += 1) {
      expect(distances[index] ?? 0).toBeGreaterThan(distances[index - 1] ?? 0)
    }
    const shortest = distances[0] ?? 0
    const longest = distances[distances.length - 1] ?? 0
    // NajniĹĽsza belka lÄ…duje za punktem K, najwyĹĽsza nie przekracza HS przy
    // bezwietrznej pogodzie â€” rekord skoczni zostaje do zdobycia na wietrze.
    expect(shortest).toBeGreaterThan(hill.spec.kPointMeters - 5)
    expect(longest).toBeLessThan(hill.spec.hillSizeMeters)
    expect(longest - shortest).toBeGreaterThan(8)
  })

  it('trafia belkÄ… odniesienia w odlegĹ‚oĹ›Ä‡ zwyciÄ™zcy z normy', () => {
    const factors = compensationFactors()
    expect(factors.winnerDistance).toBe((hill.spec.kPointMeters + hill.spec.hillSizeMeters) / 2)
    expect(Math.abs(factors.baseDistance - factors.winnerDistance)).toBeLessThan(2)
  })

  it('utrzymuje czas lotu w zakresie duĹĽej skoczni', () => {
    const sim = runJump({ gate: 8, pilot: 'ideal', style: 'telemark' })
