describe('P42 â€” geometria rozbiegu wobec normy FIS', () => {
  it('trzyma kÄ…ty, dĹ‚ugoĹ›ci i wysokoĹ›Ä‡ progu w granicach normy', () => {
    const spec = hill.spec
