tool_input.content:
/**
 * Zakres metraĹĽu krzywej widoczny w oknie kamery, poszerzony o jeden krok
 * z kaĹĽdej strony, ĹĽeby wielokÄ…ty nie urywaĹ‚y siÄ™ na krawÄ™dzi ekranu.
 */
function visibleRange(
  view: WorldView,
  curve: ProfileCurve,
  stepMeters: number,
): { from: number; to: number } | null {
  let from: number | null = null
  let to: number | null = null
  for (let meters = curve.startDistanceMeters; meters <= curve.endDistanceMeters; meters += stepMeters) {
    const screen = view.toScreen(curve.positionAt(meters))
    if (screen.x < -SCENE_MARGIN_PX || screen.x > VIEW_WIDTH + SCENE_MARGIN_PX) continue
    if (from === null) from = meters
    to = meters
  }
  if (from === null || to === null) return null
  return {
    from: Math.max(curve.startDistanceMeters, from - stepMeters),
    to: Math.min(curve.endDistanceMeters, to + stepMeters),
  }
}

/** Punkt powierzchni przesuniÄ™ty o `offsetMeters` wzdĹ‚uĹĽ normalnej, w pikselach. */
function offsetPoint(
  view: WorldView,
  curve: ProfileCurve,
  meters: number,
  offsetMeters: number,
): [number, number] {
  const base = curve.positionAt(meters)
  const normal = curve.normalAt(meters)
  const screen = view.toScreen({ x: base.x + normal.x * offsetMeters, y: base.y + normal.y * offsetMeters })
  return [screen.x, screen.y]
}

/**
 * Pas o STAĹ�EJ GRUBOĹšCI W METRACH wzdĹ‚uĹĽ powierzchni. WczeĹ›niej Ĺ›nieg rysowaĹ‚
 * siÄ™ jako polilinia o gruboĹ›ci podanej w pikselach â€” przy skali 2,075 px/m
 * pas 6 px â€žznaczyĹ‚" 2,9 m Ĺ›niegu. Teraz gruboĹ›Ä‡ jest wielkoĹ›ciÄ… Ĺ›wiata, wiÄ™c
 * zostaje prawdziwa niezaleĹĽnie od zoomu kamery.
 */
function drawSurfaceBand(
  context: CanvasRenderingContext2D,
  view: WorldView,
  curve: ProfileCurve,
  color: string,
  topOffsetMeters: number,
  bottomOffsetMeters: number,
  stepMeters: number,
): void {
  const range = visibleRange(view, curve, stepMeters)
  if (!range) return
  const top: Array<[number, number]> = []
  const bottom: Array<[number, number]> = []
  for (let meters = range.from; meters <= range.to; meters += stepMeters) {
    top.push(offsetPoint(view, curve, meters, topOffsetMeters))
    bottom.push(offsetPoint(view, curve, meters, bottomOffsetMeters))
  }
  top.push(offsetPoint(view, curve, range.to, topOffsetMeters))
  bottom.push(offsetPoint(view, curve, range.to, bottomOffsetMeters))
  if (top.length < 2) return
  fillPixelPolygon(context, color, [...top, ...bottom.reverse()])
}

/** Ziemia pod powierzchniÄ… zeskoku i wybiegu â€” wypeĹ‚nienie do doĹ‚u ekranu. */
function fillTerrainBody(context: CanvasRenderingContext2D, view: WorldView, hill: Hill): void {
  const points: Array<[number, number]> = []
  let started = false
  for (const curve of [hill.landingCurve, hill.outrunCurve]) {
    const range = visibleRange(view, curve, TERRAIN_STEP_METERS)
    if (!range) continue
    for (let meters = range.from; meters <= range.to; meters += TERRAIN_STEP_METERS) {
      points.push(offsetPoint(view, curve, meters, 0))
      started = true
    }
    points.push(offsetPoint(view, curve, range.to, 0))
  }
  if (!started || points.length < 2) return
  const first = points[0] as [number, number]
  const last = points[points.length - 1] as [number, number]
  fillPixelPolygon(context, '#152838', [
    [-SCENE_MARGIN_PX, first[1]],
    ...points,
    [VIEW_WIDTH + SCENE_MARGIN_PX, last[1]],
    [VIEW_WIDTH + SCENE_MARGIN_PX, VIEW_HEIGHT + SCENE_MARGIN_PX],
    [-SCENE_MARGIN_PX, VIEW_HEIGHT + SCENE_MARGIN_PX],
  ])
}

/**
 * Konstrukcja rozbiegu w wymiarach rzeczywistych: najazd stoi na stalowej
 * estakadzie, a jej wysokoĹ›Ä‡ roĹ›nie ku gĂłrze skoczni. Przy skali 1:1 podpory
 * co 12 m sÄ… ~139 px od siebie, wiÄ™c w kadrze widaÄ‡ jednÄ…â€“dwie naraz.
 */
function drawInrunStructure(context: CanvasRenderingContext2D, hill: Hill, view: WorldView): void {
  const palette = env()
  const curve = hill.inrunCurve
  const range = visibleRange(view, curve, 1)
  if (!range) return

  for (let meters = 6; meters <= curve.endDistanceMeters - 8; meters += 12) {
    if (meters < range.from - 12 || meters > range.to + 12) continue
    const top = view.toScreen(curve.positionAt(meters))
    // Estakada schodzi do terenu; im wyĹĽej na rozbiegu, tym jest wyĹĽsza.
    const legMeters = 4 + (curve.endDistanceMeters - meters) * 0.22
    const footY = top.y + legMeters * view.scale
    const halfTop = 1.1 * view.scale
    pixelLine(context, top.x - halfTop, top.y + 2, top.x - halfTop * 2.2, footY, '#3c5565', 2)
    pixelLine(context, top.x + halfTop, top.y + 2, top.x + halfTop * 2.2, footY, palette.steelMid, 2)
    for (let brace = 1; brace <= 3; brace += 1) {
      const t = brace / 4
      const y = top.y + (footY - top.y) * t
      const half = halfTop * (1 + 1.2 * t)
      pixelLine(context, top.x - half, y, top.x + half, y, palette.steelMid, 1)
    }
  }

  // WieĹĽa startowa nad najwyĹĽszÄ… belkÄ….
  const towerBase = view.toScreen(curve.positionAt(0))
  const wide = 3.2 * view.scale
  const high = 5.0 * view.scale
  context.fillStyle = palette.steelDark
  context.fillRect(Math.round(towerBase.x - wide * 0.5), Math.round(towerBase.y - high), Math.round(wide), Math.round(high))
  context.fillStyle = COLOR.steel
  context.fillRect(Math.round(towerBase.x - wide * 0.5), Math.round(towerBase.y - high), Math.round(wide), 1)
  context.fillStyle = COLOR.warm
  context.fillRect(Math.round(towerBase.x - wide * 0.3), Math.round(towerBase.y - high * 0.7), 4, 3)
}

/**
 * KrawÄ™dĹş progu: stalowy nos wysuniÄ™ty nad garb. WysokoĹ›Ä‡ progu nad podstawÄ…
 * skoczni (`tableClearanceMeters` = 3,03 m) jest realna i po przejĹ›ciu na
 * skalÄ™ 1:1 widaÄ‡ jÄ… jako 35 px â€” to ona robi charakterystyczny â€žbalkon"
 * skoczni, ktĂłrego przy poprzednim zoomie w ogĂłle nie daĹ‚o siÄ™ dostrzec.
 */
function drawTakeoffTable(context: CanvasRenderingContext2D, hill: Hill, view: WorldView): void {
  const edge = view.toScreen({ x: 0, y: 0 })
  if (edge.x < -80 || edge.x > VIEW_WIDTH + 80) return
  const below = view.toScreen({ x: 0, y: -hill.spec.tableClearanceMeters })
  const back = view.toScreen({ x: -hill.spec.tableClearanceMeters * 0.9, y: 0 })
  fillPixelPolygon(context, env().steelDark, [
    [back.x, back.y],
    [edge.x, edge.y],
    [edge.x, below.y],
    [back.x, below.y + 2],
  ])
  context.fillStyle = COLOR.steel
  context.fillRect(Math.round(edge.x) - 2, Math.round(edge.y) - 1, 3, 2)
}

let terrainMarkerCache: SportMarkerSet | null = null
let terrainMarkerKey = ''

function staticMarkers(hill: Hill): SportMarkerSet {
  const key = `${hill.spec.id}:${hill.spec.hillVersion}`
  if (!terrainMarkerCache || terrainMarkerKey !== key) {
    terrainMarkerCache = buildSportMarkers(hill)
    terrainMarkerKey = key
  }
  return terrainMarkerCache
}

/**
 * CaĹ‚a scena terenu rysuje siÄ™ CO KLATKÄ�, ale wyĹ‚Ä…cznie w oknie kamery.
 * Poprzednia wersja renderowaĹ‚a caĹ‚Ä… skoczniÄ™ raz do bufora i przesuwaĹ‚a go
 * `drawImage`; przy skali 1:1 ten bufor miaĹ‚by ~3500Ă—1700 px (24 MB), wiÄ™c
 * zamiast tego przycinamy metraĹĽ do tego, co widaÄ‡ (kilkadziesiÄ…t metrĂłw).
 */
function drawProductionTerrain(
  context: CanvasRenderingContext2D,
  actor: SceneActor,
  view: WorldView,
  state: TrainingSceneState,
): void {
  const hill = actor.hill
  fillTerrainBody(context, view, hill)
  drawInrunStructure(context, hill, view)

  for (const curve of [hill.landingCurve, hill.outrunCurve]) {
    drawSurfaceBand(context, view, curve, COLOR.snowShade, 0, -SNOW_DEPTH_METERS - 0.35, TERRAIN_STEP_METERS)
    drawSurfaceBand(context, view, curve, COLOR.snow, 0.06, -SNOW_DEPTH_METERS, TERRAIN_STEP_METERS)
  }
  drawSurfaceBand(context, view, hill.inrunCurve, env().steelMid, 0, -0.55, TERRAIN_STEP_METERS)
  drawSurfaceBand(context, view, hill.inrunCurve, COLOR.snow, 0.04, -0.3, TERRAIN_STEP_METERS)
  // Tory najazdu: dwa rowki po 13 cm w rozstawie 32 cm (ICR 417.1). Z boku
  // widaÄ‡ bliĹĽszy rowek i cieĹ„ dalszego â€” razem 1â€“2 px przy skali 1:1.
  drawSurfaceBand(context, view, hill.inrunCurve, env().steelDark, 0.02, -0.06, TERRAIN_STEP_METERS)

  drawTakeoffTable(context, hill, view)

  const markers = staticMarkers(hill)
  for (const band of markers.sideBands) {
    drawBothSideBands(context, view, hill, band.fromMeters, band.toMeters, colorForBand(band.kind))
  }
  context.textAlign = 'center'
  for (const marker of markers.meterLines) {
    drawSurfaceTick(context, view, hill, marker.meters, 1.05, COLOR.steel, 1)
    const normal = hill.surfaceNormalAt(marker.meters)
    const point = view.toScreen({ x: marker.point.x + normal.x * 2.2, y: marker.point.y + normal.y * 2.2 })
    if (point.x > -30 && point.x < VIEW_WIDTH + 30) {
      label(context, `${marker.meters}`, point.x, point.y + 3, COLOR.text, 6)
    }
  }
  context.textAlign = 'left'
  drawSidePaddles(context, view, hill, markers, false)
  drawNamedSportMarker(context, view, hill, markers.kPoint, 'K', COLOR.blue, false)
  drawNamedSportMarker(context, view, hill, markers.hillSize, 'HS', COLOR.red, false)
  drawNamedSportMarker(context, view, hill, markers.fallLine, 'FALL', COLOR.warm, false)

  const dynamicMarkers = buildSportMarkers(hill, {
    leadingTargetHalfMeters: state.leadingTargetHalfMeters,
    recordHalfMeters: state.recordHalfMeters,
  })
  context.textAlign = 'center'
  drawDynamicMarkers(context, view, hill, dynamicMarkers)
  context.textAlign = 'left'

  drawJumperShadow(context, view, actor)
}

