  "provider": {
    // StaĹ‚e limity kontekstu dla modeli GPT: 900 000 tokenĂłw.
    // OpenCode nie obsĹ‚uguje wildcardĂłw w provider.models â€” kaĹĽdy model GPT
    // wymaga jawnego wpisu. Lista poniĹĽej obejmuje wszystkie modele GPT
    // uĹĽywane w tym Ĺ›rodowisku (presety OMO-slim "openai" i "main" + bazowy gpt-5.6).
    // DokĹ‚adajÄ…c nowy model GPT, skopiuj ten sam blok limit.
    "openai": {
      "models": {
        "gpt-5.6": {
          "limit": {
            "context": 900000,
            "output": 128000
          }
        },
        "gpt-5.6-terra": {
          "limit": {
            "context": 900000,
            "output": 128000
          }
        },
        "gpt-5.6-sol": {
          "limit": {
            "context": 900000,
            "output": 128000
          }
        },
        "gpt-5.6-luna": {
          "limit": {
            "context": 900000,
            "output": 128000
          }
        },
        "gpt-6-astra": {
          "limit": {
            "context": 900000,
            "output": 128000
          }
        }
      }
    },
    // Kimi 3 na opencode-go udostÄ™pnia tylko jeden poziom wysiĹ‚ku: "max".
    // Preset OMO-slim "main" uĹĽywa dla niego wariantu "high", wiÄ™c ten alias
    // mapuje "high" -> "max". Bez aliasu wariant byĹ‚by ignorowany.
    "opencode-go": {
      "models": {
        "kimi-k3": {
          "variants": {
            "high": {
              "reasoningEffort": "max"
            }
          }
        }
      }
    }
  },
  // PrĂłg kompaktowania 800 000 = context (900 000) â�’ reserved (100 000).
  // OpenCode nie ma osobnego pola "threshold" â€” moment autokompakcji
  // wynika z reserved. ObowiÄ…zuje teĹĽ sesje/agenty OMO-slim, bo kompaktowanie
  // jest mechanizmem rdzenia, nie presetu.
  "compaction": {
    "auto": true,
    "reserved": 100000
  }
}

