import json,io
md=json.load(io.open(r'C:/Users/admin/.cache/opencode/models.json',encoding='utf-8'))
cfg=json.load(io.open(r'C:/Users/admin/.config/opencode/oh-my-opencode-slim.json',encoding='utf-8'))

def efforts(ref):
    prov,mid=ref.split('/',1)
    m=(md.get(prov,{}).get('models') or {}).get(mid)
    if m is None: return None
    ro=m.get('reasoning_options')
    if not ro: return []
    for o in ro:
        if o.get('type')=='effort': return o.get('values',[])
    return ['<toggle/budget>']

def check(label,entry):
    mv=entry.get('model'); items = mv if isinstance(mv,list) else [mv]
    for it in items:
        if isinstance(it,str): mid,var=it,entry.get('variant')
        else: mid,var=it['id'],it.get('variant',entry.get('variant'))
        ev=efforts(mid)
        if ev is None: st='MODEL NIE ISTNIEJE'
        elif ev==['<toggle/budget>']: st='OK (toggle/budget)'
        elif var in ev: st='OK'
        elif ev==[] and var is None: st='OK (bez wariantu)'
        else: st=f'ZLY WARIANT (dostepne: {ev})'
        print(f"{label:22s} {mid:45s} {str(var):6s} -> {st}")

print('--- preset main ---')
for a,e in cfg['presets']['main'].items(): check(a,e)
print('--- councillors ---')
for n,e in cfg['council']['presets']['default'].items(): check('councillor:'+n,e)
EOF

