import io
p="opencode.jsonc"; s=io.open(p,encoding="utf-8").read()

o1 = '''    // wymaga jawnego wpisu. Lista poniĹĽej obejmuje wszystkie modele GPT
    // uĹĽywane w tym Ĺ›rodowisku (presety OMO-slim "openai" i "main" + bazowy gpt-5.6).
'''
n1 = '''    // wymaga jawnego wpisu. Lista poniĹĽej obejmuje WSZYSTKIE 9 modeli GPT-6
    // widocznych w katalogu (openai: sol/luna/astra + ich warianty -fast;
    // opencode: sol/luna/astra) oraz modele gpt-5.6 presetu "openai".
    // Weryfikacja pokrycia: opencode models --verbose | (limit per model).
'''

o2 = '''  // PrĂłg autokompakcji GPT = 800 000. OpenCode liczy go jako
  // limit.input (900 000) â�’ reserved (100 000); stÄ…d jawne "input" wyĹĽej.
  // Nie ma osobnego pola "threshold". ObowiÄ…zuje teĹĽ sesje/agenty OMO-slim, bo kompaktowanie
  // jest mechanizmem rdzenia, nie presetu.
'''
n2 = '''  // PrĂłg autokompakcji GPT-6 = 800 000. FormuĹ‚a z rdzenia OpenCode 1.18.31:
  //   reserved = cfg.compaction.reserved ?? min(20000, maxOutputTokens)
  //   prĂłg = limit.input ? max(0, limit.input - reserved)
  //                      : max(0, limit.context - maxOutputTokens)
  // StÄ…d 900 000 â�’ 100 000 = 800 000 i stÄ…d jawne "input" w kaĹĽdym bloku wyĹĽej:
  // bez "input" prĂłg policzyĹ‚by siÄ™ z gaĹ‚Ä™zi context i wyszedĹ‚by inny.
  // Nie ma osobnego pola "threshold". ObowiÄ…zuje teĹĽ sesje/agenty OMO-slim, bo kompaktowanie
  // jest mechanizmem rdzenia, nie presetu.
  // Uwaga: "reserved" jest globalne. Model fallbackowy
  // opencode-go/muse-spark-1.3-contributor nie ma limit.input, wiÄ™c idzie drugÄ…
  // gaĹ‚Ä™ziÄ… (context 1 048 576 â�’ maxOutput) i nie korzysta z tej wartoĹ›ci.
'''
for o,n in ((o1,n1),(o2,n2)):
    assert s.count(o)==1, (s.count(o), o[:40])
    s=s.replace(o,n)
io.open(p,"w",encoding="utf-8").write(s)
print("comments updated")
PY

