import { buildHill, type HillSpec } from 'C:/retro-ski-jumping/src/simulation/technicalHill'
import { PLANICA_FLYING } from 'C:/retro-ski-jumping/src/simulation/hills/planicaFlying'
import { JumpSimulation, SIM_DT } from 'C:/retro-ski-jumping/src/simulation/jump'
import { DEFAULT_JUMP_PARAMS } from 'C:/retro-ski-jumping/src/simulation/params'
import { COEFFICIENT_CURVE, type CoefficientPoint } from 'C:/retro-ski-jumping/src/simulation/aero'
