import { CompetitionSession } from 'C:/retro-ski-jumping/src/app/competitionSession'
import { createTrainingJumpResult } from 'C:/retro-ski-jumping/src/sport/jumpResult'
import { EMPTY_INPUT, makeInput } from 'C:/retro-ski-jumping/tests/support/jumpHarness'

type Hill = ReturnType<typeof buildHill>
const edgesByHill = new WeakMap<Hill, Map<number, number>>()
function edgeTick(hill: Hill, gate: number): number {
  let edges = edgesByHill.get(hill); if (!edges) { edges = new Map(); edgesByHill.set(hill, edges) }
  const c = edges.get(gate); if (c !== undefined) return c
  const sim = new JumpSimulation({ hill, gateNumber: gate, autoStart: true })
  while (sim.phase === 'Inrun' || sim.phase === 'Takeoff') sim.step(EMPTY_INPUT)
  edges.set(gate, sim.tick); return sim.tick
}
type Trial = { gate: number; wind: number; offset?: number; prep?: number; style?: 'parallel' | 'telemark' | null; aoa?: number; windField?: WindField }
function run(hill: Hill, trial: Trial): JumpSimulation {
  const wf = { seed: 42, version: 'h04-constant-wind-v1', sampleUserMetersPerSecond: () => trial.wind } as WindField
  const sim = new JumpSimulation({ hill, gateNumber: trial.gate, windField: trial.windField ?? wf, autoStart: true })
  const takeoffTick = edgeTick(hill, trial.gate) - Math.round(DEFAULT_JUMP_PARAMS.takeoff.idealLeadSeconds / SIM_DT) + (trial.offset ?? 0)
  let prepped = false
  for (let g = 0; g < 20000 && !sim.finished; g++) {
    const pressed: ('takeoff' | 'telemark' | 'parallel')[] = []; const held: ('left' | 'right')[] = []
    if (sim.tick === takeoffTick) pressed.push('takeoff')
    if (sim.phase === 'Flight') {
      const desired = Math.atan2(sim.velocity.y, sim.velocity.x) * 180 / Math.PI + (trial.aoa ?? 32)
      const cur = sim.targetPitchRad * 180 / Math.PI
      if (cur > desired + 0.5) held.push('right'); else if (cur < desired - 0.5) held.push('left')
      if (!prepped && trial.style !== null && sim.flightSeconds >= (trial.prep ?? 5)) { pressed.push(trial.style ?? 'parallel'); prepped = true }
    }
    sim.step(makeInput(pressed, held, sim.tick))
  }
  return sim
}
// Browser-like pilot: lagged snapshot, periodic key decisions, flow+aoa, R at 5 s or (3 s and h<=1.6).
function browserPilot(hill: Hill, gate: number, field: WindField, offset: number, lag: number, period: number, aoa = 29): JumpSimulation {
  const sim = new JumpSimulation({ hill, gateNumber: gate, windField: field, autoStart: true })
  const takeoffTick = edgeTick(hill, gate) - Math.round(DEFAULT_JUMP_PARAMS.takeoff.idealLeadSeconds / SIM_DT) + offset
  const hist: { phase: string; flow: number; target: number; fs: number; h: number }[] = []
  let held: 'left' | 'right' | null = null; let sent = false; let pendingLanding = -1
  for (let g = 0; g < 20000 && !sim.finished; g++) {
    hist.push({ phase: sim.phase, flow: Math.atan2(sim.velocity.y, sim.velocity.x) * 180 / Math.PI, target: sim.targetPitchRad * 180 / Math.PI, fs: sim.flightSeconds, h: sim.phase === 'Flight' ? sim.heightAboveSurface() : 99 })
    const pressed: ('takeoff' | 'parallel')[] = []
    if (sim.tick === takeoffTick) pressed.push('takeoff')
    const seen = hist[Math.max(0, hist.length - 1 - lag)]!
    if (sim.tick % period === 0 && seen.phase === 'Flight' && !sent) {
      const desired = seen.flow + aoa
      held = seen.target > desired + 0.5 ? 'right' : seen.target < desired - 0.5 ? 'left' : null
      if (seen.fs >= 5 || (seen.fs >= 3 && seen.h <= 1.6)) { held = null; sent = true; pendingLanding = sim.tick + 1 }
    }
    if (sim.tick === pendingLanding && sim.phase === 'Flight') pressed.push('parallel')
    sim.step(makeInput(pressed, held ? [held] : [], sim.tick))
  }
  return sim
}
function sweep(hill: Hill) {
  const samples = [...Array.from({ length: 33 }, (_, i) => (i - 16) / 5), -0.01, 0.01, -0.0001, 0.0001]
  let prev = selectSafeJuryGate(hill, -3.2).gateNumber; const switches: number[] = []
  for (let s = -3199; s <= 3200; s++) { const w = s / 1000; const g = selectSafeJuryGate(hill, w).gateNumber; if (g !== prev) { switches.push(w); prev = g } }
  for (const b of switches) for (const d of [-0.002, 0, 0.002]) { const w = b + d; if (w > -3.2 && w < 3.2) samples.push(w) }
  const full = new Set([0, -0.0001, 0.0001, ...switches.flatMap(w => [w - 0.001, w])])
  let wt = 0, wh = 0, wtAt = '', whAt = ''
  for (const wind of [...new Set(samples), ...full]) {
    if (wind < -3.2 || wind > 3.2) continue
    const field = { seed: 42, version: 'h04-constant-wind-v1', sampleUserMetersPerSecond: () => wind } as WindField
    const gate = selectSafeJuryGate(hill, forecastWindMean(field, hill)).gateNumber
    const trials = full.has(wind)
      ? [24, 26, 28, 30, 32, 34, 36].flatMap(aoa => [-4, 0, 4, 8].flatMap(offset => [7, 9, null].map(prep => run(hill, { gate, wind, windField: field, aoa, offset, prep: prep ?? undefined, style: prep === null ? null : 'parallel' }))))
      : [26, 30, 34].flatMap(aoa => [0, 4].flatMap(offset => [9, null].map(prep => run(hill, { gate, wind, windField: field, aoa, offset, prep: prep ?? undefined, style: prep === null ? null : 'parallel' }))))
    const raw = Math.max(...trials.map(s => s.measuredDistanceMeters ?? 0))
    if (wind < 0 && raw > wt) { wt = raw; wtAt = `g${gate} w${wind}` }
    if (wind >= 0 && raw > wh) { wh = raw; whAt = `g${gate} w${wind}` }
