  const field = (session as unknown as { currentWindField: WindField }).currentWindField
  const cGate = session.snapshot().juryGateNumber
  const comp: number[] = []
  const detail: string[] = []
  for (const lag of config.lags ?? [2, 3]) for (const period of config.periods ?? [2, 3]) for (const offset of config.offsets ?? [-4, -2, 0, 2, 4]) {
    const s = browserPilot(hill, cGate, field, offset, lag, period)
    if (config.detail) { const ev = s.events.filter(e => ['takeoffImpulseStart','takeoffEdge','landingPrep','contact'].includes(e.type)).map(e => e.type[0]+e.tick).join(','); detail.push(`o${offset} l${lag} p${period}: ${s.outcome?.status} ${s.measuredDistanceMeters?.toFixed(1)} [${ev}]`) }
    comp.push(s.outcome?.status === 'landed' ? (s.measuredDistanceMeters ?? 0) : 0)
  }
  comp.sort((a, b) => a - b)
  const nominal = run(hill, { gate: 6, wind: 0, prep: 5 })
  const nominal28 = run(hill, { gate: 6, wind: 0, prep: 5, aoa: 28 })
  const strong = run(hill, { gate: 1, wind: 3.2, aoa: 28, prep: 5 })
  const rec = run(hill, { gate: 42, wind: 0, prep: 5 })
  const out = {
    label, compGate: cGate, forecast: forecastWindMean(field, hill).toFixed(2),
    comp: { min: comp[0]!.toFixed(1), med: comp[Math.floor(comp.length / 2)]!.toFixed(1), max: comp.at(-1)!.toFixed(1), n: comp.length, below180: comp.filter(d => d < 180).length },
    nominal: `${nominal.outcome?.status} ${nominal.measuredDistanceMeters?.toFixed(2)}`,
    nominal28: `${nominal28.outcome?.status} ${nominal28.measuredDistanceMeters?.toFixed(2)}`,
    strong: `${strong.outcome?.status} ${strong.measuredDistanceMeters?.toFixed(2)} h${strong.contact?.supportHands}`,
    record: `${rec.outcome?.status} ${rec.measuredDistanceMeters?.toFixed(3)} h${rec.contact?.supportHands} save ${createTrainingJumpResult(rec, 1).distanceHalfMeters / 2}`,
    ...(doSweep ? sweep(hill) : {}),
  }
  console.log(JSON.stringify(out)); if (detail.length) console.log(detail.join('
'))
}
function withPoints(points: CoefficientPoint[]): CoefficientPoint[] {
  const keep = COEFFICIENT_CURVE.filter(p => p.angleOfAttackDeg <= 26 || p.angleOfAttackDeg >= 40)
  return [...keep, ...points].sort((a, b) => a.angleOfAttackDeg - b.angleOfAttackDeg)
}
type Config = { sweep: boolean; base: boolean; detail?: boolean; lags?: number[]; periods?: number[]; offsets?: number[]; candidates: Record<string, CoefficientPoint[]> }
const config = JSON.parse(readFileSync('C:/Users/admin/AppData/Local/Temp/claude/C--retro-ski-jumping/5ce9651b-d45a-4bf3-9b26-325f80524702/scratchpad/probe/probe.json', 'utf8')) as Config
